(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).ezek={"1":{"1":"На тридцатый год, в пятый день четвертого месяца – я находился тогда среди переселенцев, у реки Кевар – разверзлись небеса, и было мне видение от Бога…","2":"В пятый день месяца – это был пятый год после пленения царя Иехонии –","3":"в стране халдеев, у реки Кевар, Господь возвестил Свое слово священнику Иезекиилю, сыну Бузи ; там простер Господь над ним Свою руку.","4":"…И видел я: с севера надвигается буря, огромная туча, пронизанная огнем. Сияние окружает ее.","5":"А там, внутри огня, – словно бы янтарь; там виднелись очертания четырех существ. И подобны они были человеческим фигурам,","6":"но у каждого по четыре лица и у каждого по четыре крыла.","7":"Их ноги были прямые, ступни – как бычьи копыта, и сверкали они, словно отполированная медь.","8":"Под крыльями, с четырех сторон, у них были человеческие руки. Лица и крылья у всех четверых были такие:","9":"крылья их касались друг друга, и куда бы ни направлялись существа, им не надо было поворачиваться – все они двигались лицом вперед.","10":"Очертания их лиц были такие: лицо человека, справа от него у всех четверых – лицо льва, слева у всех четверых – лицо быка, и еще одно лицо у всех четверых – лицо орла.","11":"Лица и крылья у них были такие: крылья подняты вверх и распростерты, и двумя крыльями существа касались друг друга, а двумя другими прикрывали свое тело;","12":"двигались они всегда лицом вперед – куда Духу угодно было направиться, туда они и шли, не поворачиваясь.","13":"Фигуры существ были подобны раскаленным углям в пламени, они пылали, словно факелы в огне, и огонь меж существами двигался вместе с ними. Сверкал огонь, из него вырывались молнии.","14":"И сами существа неслись и метались, подобно молниям.","15":"Я взглянул на них и увидел на земле, перед каждым из этих четырехликих существ, по колесу.","16":"Казалось, будто сделаны эти колеса из хризолита, и очертания у всех четырех были одинаковые: каждое колесо словно бы состояло из двух, вложенных друг в друга.","17":"Когда они перемещались, то, не меняя направления, они могли двигаться в любую из четырех сторон.","18":"А их ободья – высоки они были и ужасны – ободья у всех четырех со всех сторон были усеяны глазами.","19":"Когда двигались существа, подле них двигались и колеса, когда же поднимались существа над землей, вместе с ними поднимались и колеса.","20":"Куда Духу угодно было направиться – туда и шли существа. Куда было угодно направиться Духу – вместе с существами поднимались и колеса, ибо и в колесах был Дух существ.","21":"Когда двигались существа, двигались и колеса, когда существа останавливались – колеса останавливались, когда существа поднимались над землей – вместе с ними поднимались и колеса, ибо и в колесах был Дух существ.","22":"А над головами существ были очертания свода. Внушая трепет, он сверкал, словно ледник, и распростирался над их головами.","23":"А под ним, касаясь друг друга, вздымались их распрямленные крылья. Двумя другими крыльями каждое существо прикрывало свое тело.","24":"Когда они двигались, я слышал гул крыльев, подобный гулу бушующего моря, голосу Всесильного, – словно гул битвы, словно шум воинства. Когда же существа остановились, они опустили крылья.","25":"Когда существа остановились, они опустили крылья. И тогда над сводом, что был распростерт над их головами, раздался голос.","26":"Там, над сводом, распростертым над их головами, был словно бы лазурит; там виднелись очертания трона. А над очертаниями трона – словно бы фигура человека.","27":"И видел я выше очертаний поясницы словно бы янтарь, объятый огнем. А ниже очертаний поясницы я видел словно бы огонь, окруженный сиянием.","28":"Как радуга, появившаяся на небе во время дождя, так окружало Его сияние."},"2":{"1":"Таким предстал мне образ Славы Господней. Когда я увидел это, я пал ниц и услышал голос. Он сказал мне: «Встань, человек! Я буду говорить с тобою».","2":"И когда он сказал так, вошел в меня Дух, поднял меня и поставил на ноги. И услышал я Того, кто обращался ко мне.","3":"Он сказал мне: «Человек! Я посылаю тебя к сынам Израилевым, к племени отступников, которое против Меня восстало. Как отцы их против Меня восставали, так и сами они до сих пор против Меня восстают!","4":"О сыновья упрямые и наглые! Я посылаю тебя к ним, обратись к ним со словами: „Так говорит Господь Бог!\"","5":"И будут ли они тебя слушать, или не будут – все равно поймет это упрямое племя, что был среди них пророк.","6":"А ты, человечий сын, не бойся их, не бойся их речей, хотя вокруг тебя тернии и шипы, ты живешь среди скорпионов! Не бойся их речей, не страшись никого из этого упрямого племени!","7":"Передай им Мое слово, будут ли тебя слушать или не будут эти своевольные люди!","8":"А ты, человек, слушай то, что Я говорю тебе, не будь упрямым, как это упрямое племя. Открой уста и ешь то, что Я даю тебе».","9":"И увидел я: простерта ко мне рука, а в ней – свиток.","10":"Он развернул передо мной свиток, и оказалось, что свиток исписан с обеих сторон, и с лицевой, и с обратной, и записаны в нем плачи, крики и стоны."},"3":{"1":"Он сказал мне: «Человек! Ешь то, что ты видишь, ешь этот свиток! А потом иди и говори с народом Израилевым!»","2":"Я открыл уста, и Он заставил меня съесть свиток.","3":"Он сказал мне: «Человек! Ешь досыта, наполни живот этим свитком, который Я даю тебе!» Я стал есть, и свиток был в моем рту сладок, как мед.","4":"Он сказал мне: «Человек! Иди к народу Израилеву и передавай им Мои слова!","5":"Ты послан не к иному какому-то народу, чей язык темен и речь непонятна, а к народу Израилеву.","6":"Ты послан не к тем многочисленным народам, чей язык темен и речь непонятна, чьи слова ты не в силах разобрать. Но даже эти народы – если бы Я послал тебя к ним – выслушали бы тебя!","7":"А народ Израилев слушать тебя не захочет, потому что Меня не хочет он слушать! Весь народ Израилев упрям и дерзок.","8":"Но и тебя Я сделаю упрямым, как они упрямы, и тебя сделаю дерзким, как они дерзки.","9":"Сделаю тебя как алмаз, тверже кремня, и потому не бойся, не страшись никого из этого упрямого племени!»","10":"Он сказал мне: «Человек! Все, что Я скажу тебе, сохрани в своем сердце, слушай внимательно!","11":"Иди к переселенцам, к сынам твоего народа, и – будут ли они тебя слушать или нет – обратись к ним со словами: „Так говорит Господь Бог!\"»","12":"И поднял меня Дух, и я услышал позади гул страшного землетрясения – это Слава Господня поднималась над землей –","13":"и шум хлопающих крыльев, и грохот колес, и гул страшного землетрясения…","14":"Дух поднял меня и унес оттуда. И пошел я, преисполненный горечью и гневом, ибо тяжела была рука Господня, простертая надо мною.","15":"Я пришел к переселенцам, жившим у реки Кевар, в Тель – Авиве. И там, где они жили, семь дней я сидел перед ними, в оцепенении.","16":"А когда прошли эти семь дней, было мне слово Господа:","17":"«Человек! Я поставил тебя дозорным для народа Израилева! Ты будешь слушать слово из Моих уст и будешь предупреждать народ Израилев о Моих приговорах.","18":"Если Я вынес злодею приговор: „ты умрешь\", а ты, человек, не предупредишь его, не предостережешь от преступного пути, чтобы спасти его жизнь, тогда этот злодей умрет за свои преступления, и тебя Я призову к ответу за его смерть!","19":"Если же ты предостерегал злодея, а он все равно не оставил своих злодеяний, преступного своего пути, тогда он умрет за свои преступления, но ты избежишь кары.","20":"Если праведник отрекся от своей праведности, стал делать зло, Я по – ставлю камень на его пути, он споткнется об этот камень и погибнет. Если ты не предостерег праведника от греха – и потому он погиб и не зачлись ему добрые дела, которые он совершал раньше, то Я призову и тебя к ответу за его смерть!","21":"Если же ты предостережешь праведника, чтобы он не грешил, и он не станет грешить, то и он будет жив – благодаря твоему наставлению – и ты избежишь кары».","22":"Там Господь простер надо мной Свою руку. Он сказал мне: «Ступай в Долину, там Я буду говорить с тобой».","23":"Я вышел в Долину и увидел: там стоит Слава Господня. Она была такой же, какой я видел ее при реке Кевар. Я пал ниц.","24":"Дух вошел в меня, поднял, поставил на ноги, и Господь говорил со мной. Он сказал мне: «Иди, запрись в своем доме.","25":"Человек! Свяжут тебя веревками, опутают, и ты не сможешь выходить к людям.","26":"Твой язык Я заставлю прилипнуть к нёбу, ты онемеешь и не сможешь обличать это упрямое племя!","27":"Но когда Я заговорю с тобою, то открою твои уста, и ты обратишься к ним со словами: „Так говорит Господь Бог!\" Кто из этого упрямого племени хочет слушать, пусть услышит, а кто не хочет слушать – пусть не слышит!"},"4":{"1":"А ты, человек, возьми кирпич, положи его перед собой и нарисуй на нем город – Иерусалим.","2":"Устрой против него осаду: воздвигни осадные сооружения, насыпь вал, окружи город военным станом и поставь вокруг него стенобитные орудия.","3":"Возьми железный противень и поставь его, как железную стену, между собой и городом. Обрати свой взор против города, и пусть город будет в осаде, ты будешь осаждать его! Все это – знак для народа Израилева.","4":"Ляг на левый бок и возложи на себя грехи народа Израилева; все время, пока ты будешь лежать на левом боку, на тебе будут грехи народа Израилева.","5":"Я назначаю тебе столько дней, сколько лет он грешил, – триста девяносто дней ты будешь нести грехи народа Израилева.","6":"Когда исполнишь это, снова ляг – теперь на правый бок. Сорок дней ты будешь нести грехи народа Иуды. Каждый день Я буду тебе засчитывать за год.","7":"Обрати свой взор против осажденного Иерусалима, засучи рукава, занеси руку и пророчествуй против него.","8":"Я свяжу тебя веревками, и ты не сможешь повернуться с бока на бок, пока осада твоя не закончится.","9":"Возьми себе пшеницы, ячменя, бобов, чечевицы, проса, полбы и смешай все в одном сосуде. Это будет твоей пищей все то время, пока ты будешь лежать на боку – триста девяносто дней ты будешь есть это.","10":"И еду свою ты станешь отмерять на вес, в день – по двадцать шекелей, и есть будешь лишь от случая к случаю.","11":"Воду будешь пить по глотку, в день – по одной шестой гина, и пить будешь лишь от случая к случаю.","12":"Вот такие ячменные лепешки ты и будешь есть, а печь их будешь на человеческом кале. Пусть все это видят!»","13":"И сказал Господь: «Так и сыны Израилевы будут есть нечистую пищу среди народов, к которым Я изгоню их!»","14":"И сказал я: «О Господь Бог! Никогда в жизни я не осквернял себя, не ел ни падали, ни мяса животных, растерзанных дикими зверьми, никогда не брал я в рот оскверненного мяса!»","15":"И сказал мне Господь: «Я позволяю тебе вместо человеческого кала взять коровий навоз, и на нем ты будешь готовить себе еду».","16":"Он сказал мне: «Человек! Я лишу Иерусалим хлеба! Будут есть они по краюшке хлеба, дрожа от страха, по глотку воды будут пить, объятые ужасом,","17":"будут голодать они, изнывать от жажды. Все они от ужаса оцепенеют, за свои грехи сгниют заживо."},"5":{"1":"Человек! Возьми острый меч и, словно бритвой брадобрея, обрей себе голову, сбрей бороду! Возьми весы и раздели волосы на части.","2":"Треть сожги посреди города, когда завершится эта осада, другую треть мечом изруби вокруг города, а последнюю треть развей по ветру, – и Я обнажу меч против них!","3":"Но немного волос оставь и завяжи их в подол своей одежды.","4":"Потом возьми часть этих волос, брось в огонь и сожги. И от этого огонь перейдет на весь народ Израилев!»","5":"Так говорит Господь Бог: все это – об Иерусалиме! Я поставил его среди народов, в самой середине, а прочие страны – вокруг него.","6":"Но восстал он против Моих законов, стал нечестивее этих народов, восстал против Моих повелений, стал нечестивее стран окрестных, ибо жители его законы Мои отвергли, повелений Моих не выполняют!","7":"Потому так говорит Господь Бог: вы непокорнее народов, которые вас окружают, повелений Моих вы не выполняете, по законам Моим не живете, а живете по законам народов, которые вас окружают. Вот за это, –","8":"так говорит Господь Бог, – Я иду против тебя, Иерусалим. Я сам совершу суд посреди Иерусалима, на глазах у этих народов.","9":"За все мерзости твои, Иерусалим, Я сделаю с тобою то, чего не делал никогда раньше и чего потом уже никогда не сделаю.","10":"Отцы будут есть сыновей в Иерусалиме, и сыновья будут есть отцов. Я совершу суд над тобою, столица, а тех, кто выживет, Я развею по всем ветрам!","11":"Клянусь Собою, – говорит Господь Бог, – за то, что святилище Мое ты осквернила гнусными своими мерзостями, Я сам обрею тебя наголо, не пощажу, не помилую!","12":"Треть твоих жителей умрет от мора, от голода погибнет в городе. Треть падет от меча возле твоих стен. Треть Я развею по всем ветрам и буду гнать их мечом.","13":"Лишь тогда иссякнет Мой гнев на них, и Я утолю Мою ярость – и успокоюсь. И когда Я утолю Мою ярость, тогда поймут, что Я, Господь, судил их в ревности Моей.","14":"Я превращу тебя, Иерусалим, в руины, обреку тебя на позор среди окрестных народов – все прохожие будут видеть твой позор!","15":"Ты станешь примером позора, предметом насмешек, предостережением и ужасом для окрестных народов, – когда Я совершу над тобою Мой суд, в гневе и ярости, когда в ярости тебя покараю! Так говорю Я, Господь!","16":"Я пошлю на вас лютые стрелы голода, чтобы вас погубить, пошлю их, чтобы вас уничтожить! Я заставлю вас изнывать от голода, отниму у вас хлеб.","17":"Я пошлю на тебя голод и лютых зверей, они будут убивать твоих сыновей. Мор и смерть обрушатся на тебя. Я нашлю на тебя меч! Так говорю Я, Господь!"},"6":{"1":"И было мне слово Господа:","2":"«Человек! Обрати свой взор против гор Израильских и произнеси против них пророчество!","3":"Скажи им: „Горы Израильские! Слушайте слово Господа Бога! Так говорит Господь Бог горам, холмам, лощинам и долинам: Я на вас пошлю меч, Я разрушу капища ваши!","4":"Ваши жертвенники будут опустошены, кумирни – разбиты. Трупы жителей ваших Я брошу перед идолами вашими!","5":"Трупы сыновей Израилевых Я брошу перед их идолами, кости ваши Я разбросаю вокруг ваших жертвенников!","6":"Всюду, где вы живете, города ваши будут разрушены, опустошены капища! Да будут жертвенники ваши разрушены и разорены, идолы ваши – разбиты и на куски расколоты, кумирни – уничтожены! Да сгинут все дела ваших рук!","7":"Пусть многие из вас погибнут – и тогда вы поймете, что Я – Господь!","8":"Но некоторых из вас Я оставлю в живых – спасутся они от меча и будут рассеяны по земле, среди народов.","9":"И те, кто выживут, вспомнят обо Мне среди народов, у которых окажутся в плену, вспомнят, как Я сокрушил их развратные сердца, которые от Меня отвернулись, их развратные глаза, которые смотрели на идолов. И тогда они станут сами себе отвратительны за все свои злодеяния и мерзости,","10":"и поймут, что Я – Господь, что недаром Я осудил их и обрек на это несчастье\"».","11":"Так говорит Господь Бог: бей в ладоши, топай ногами, кричи: «Горе гнусным мерзостям народа Израилева!» От меча, от голода, от мора он погибнет!","12":"Те, кто далеко отсюда, умрут от болезней, те, кто рядом, падут от меча, а кто в осаде останется, умрет от голода! Я сполна изолью на них Мою ярость!","13":"И поймете, что Я – Господь, когда трупы их будут валяться перед их идолами, вокруг жертвенников, на всяком холме высоком, на вершинах гор, под каждым деревом цветущим, под каждым ветвистым дубом, там, где благоуханный дым жертв они идолам своим возносили!","14":"Я простираю против них Мою руку, Я опустошу всю эту землю, сделаю ее ужасом – от Пустыни и до Ривлы, всюду, где они обитают! И поймут они, что Я – Господь!"},"7":{"1":"И было мне слово Господа:","2":"«Человек! Так говорит Господь Бог о стране Израилевой: гибель! Гибель постигнет эту землю – от края до края!»","3":"Гибель тебе, страна, на тебя Я обрушу Мой гнев! Я судить тебя буду по твоим делам, призову к ответу за все твои мерзости,","4":"не пощажу тебя, не помилую! За дела твои призову тебя к ответу, за мерзости, которым ты предаешься, и тогда поймете вы, что Я – Господь!","5":"Так говорит Господь Бог: вот, беда за бедой приходит!","6":"Гибель идет, идет гибель! Тебя она погубит! Вот, близится,","7":"близится кара ваша, о жители страны! Час настает, день недалек: на горах ваших не радость будет, но ужас!","8":"Скоро Я изолью на тебя Мою ярость, сполна изолью на тебя Мой гнев! Я буду судить тебя по твоим делам, призову к ответу за все твои мерзости,","9":"не пощажу тебя, не помилую! За дела твои призову тебя к ответу, за мерзости, которым ты предаешься, и тогда поймете вы, что Я – Господь карающий!","10":"Смотрите, вот этот день! Смотрите, близится, грядет ваша кара! Жезл зацвел, расцвела гордыня:","11":"и поднялось насилье, как жезл нечестивый! Никого из них не останется, никого из их сборища не останется, никого из них, шумящих, не останется! И некому будет их оплакивать.","12":"Час настает, день приходит! Кто купил – не радуйся, кто продал – не плачь, ибо на все это сборище обрушится гнев!","13":"Продавший не успеет вернуть себе проданное, пока продавец и покупатель еще будут в живых, ибо исполнится видение об этом сборище, и никто не устоит, кто живет во грехе!","14":"Трубят они в трубы, все приготовили, да только идти на войну некому, ибо гнев Мой на все их сборище обрушился!","15":"Меч – снаружи, мор и голод – внутри! Те, кто вне города, умрут от меча, тех, кто в городе, мор и голод убьют!","16":"А кто выживет, те будут ютиться в горах, словно голуби в расщелинах скал. Все они зарыдают горько, каждый – о своем преступленье!","17":"Руки их обессилеют, мокрыми станут колени.","18":"Дерюгой они опояшутся, дрожь станет их одеянием. Стыд покроет их лица, головы их будут обриты.","19":"Серебро свое на улицу выбросят, золото для них будет, что грязь. Не спасут их серебро и золото в день Господнего гнева. Не утолят они голод серебром и золотом, живота своего не наполнят! За свои грехи погибают они!","20":"Драгоценностями своими они гордились, идолов из них изготовляли – мерзость гнусную! Но за это Я сделаю так, что эти драгоценности будут для них, что грязь!","21":"Чужеземцам отдам в добычу, злодеям земли – на разграбленье, пусть оскверняют драгоценности их.","22":"Я от них отвернусь, пусть грабители ворвутся в страну, пусть осквернят сокровищницу Мою, пусть ее осквернят!","23":"Сделай цепь, ибо страна эта полна кровавым беззаконием, столица полна насилием.","24":"Приведу Я лютые народы, ваши дома они захватят! Я положу конец гордыне сильных, будут осквернены ваши святыни.","25":"Идет ужас! Станут искать мира, но не найдут!","26":"Будет беда приходить за бедою, весть – за вестью. И станут спрашивать у пророков видений, но не будет наставления у священников и совета – у старцев.","27":"Царь зарыдает, ужас охватит вельмож, и народ страны обессилеет. Я воздам им по их поступкам, Я буду судить их за неправый их суд, и поймут они, что Я – Господь!"},"8":{"1":"В шестой год, в пятый день шестого месяца я был в своем доме, и старейшины Иудеи сидели передо мною. И вот, коснулась меня рука Господа Бога.","2":"И я увидел перед собой словно бы человеческий облик. Ниже очертаний поясницы был он огненным, а выше поясницы – словно зарево; сверкал он, как янтарь.","3":"И простер Он очертание руки и взял меня за пучок волос на голове. Дух поднял меня между землей и небом и перенес меня в Иерусалим – в видении, ниспосланном от Бога, – к северным воротам внутреннего двора, туда, где восседает ненавистный идол, вызывающий ярость Господа.","4":"И там я увидел Славу Бога Израилева – тот же облик, что я видел в Долине.","5":"Он сказал мне: «Человек! Посмотри на север!» Я посмотрел на север – и к северу от ворот жертвенника, прямо у входа, увидел этого ненавистного идола.","6":"Господь сказал мне: «Человек! Ты видишь, что они делают? Видишь великие мерзости, которые совершает здесь народ Израилев? Из-за них Я покину Мое святилище! Но смотри дальше, и увидишь мерзости еще большие!»","7":"Он перенес меня ко входу во двор Храма, и я увидел в стене щель.","8":"Он сказал мне: «Человек! Сделай пролом в стене». Я сделал пролом в стене, и передо мной открылся проход.","9":"Он сказал мне: «Иди и смотри на отвратительные мерзости, которые они здесь творят!»","10":"Я вошел и увидел, что все стены, куда ни глянь, испещрены изображениями кишащих тварей, омерзительных животных и всяких идолов, которым поклоняется народ Израилев.","11":"Семьдесят человек из числа старейшин народа Израилева стояли перед ними, и среди этих семидесяти – Яазания, сын Шафана. Каждый держал в руках ковш для воскурений, и облако благовонного дыма поднималось кверху.","12":"Он сказал мне: «Ты видишь, человек, что совершают во тьме старейшины народа Израилева, что делает каждый из них в своих покоях, испещренных изображениями? Говорят они: „Не видит нас Господь, оставил Господь эту землю!\"»","13":"Он сказал мне: «Но смотри дальше, и увидишь еще большие мерзости, которые они совершают!»","14":"Он перенес меня к северным воротам Дома Господня, и там я увидел: сидят женщины и оплакивают Таммуза.","15":"Он сказал мне: «Ты видишь это, человек? Но смотри дальше, и ты увидишь еще большие мерзости!»","16":"Он перенес меня во внутренний двор Храма Господня, и я увидел у входа во Храм, между жертвенником и притвором, человек двадцать пять мужчин. Спиной они были обращены к Храму Господа, а лицом – на восток, и простирались они ниц перед Солнцем.","17":"Он сказал: «Ты видишь это, человек? Неужели народу Иуды мало тех мерзостей, которые он совершает здесь? Но они и всю страну наполнили беззаконием, вновь и вновь вызывают Мой гнев. Вот подносят они ветви к своим носам…","18":"За все это Я покараю их в ярости Моей, не пощажу, не помилую. Они будут звать Меня, громко кричать, но Я не буду их слушать!»"},"9":{"1":"И воскликнул Он громовым голосом: «Подойдите те, кому поручено покарать этот город; каждый – со своим смертоносным оружием!»","2":"И я увидел: от верхних ворот, обращенных к северу, идут шестеро и у каждого из них – орудие разрушения. И еще среди них был один, одетый в льняные одежды; к поясу у него были прикреплены принадлежности писца. Они приблизились и остановились возле медного жертвенника.","3":"Слава Бога Израилева поднялась с херувима, на котором она пребывала, и остановилась на пороге Храма. И обратившись к тому, кто был одет в льняные одежды, с принадлежностями писца на поясе,","4":"Господь повелел: «Пройди по этому городу, по Иерусалиму, и поставь знак на лбу тех, кто плачет и стонет, видя какие мерзости творятся в Иерусалиме».","5":"И я услышал, как Он сказал остальным: «Идите за ним по городу и убивайте! Не щадите никого, будь – те безжалостны!","6":"Стариков, юношей и дев, детей и женщин – всех убивайте, всех уничтожайте, но не трогайте тех, у кого будет этот знак. Начните с Моего Святилища». И они начали со старцев, которые находились перед Храмом.","7":"Он сказал тем шестерым: «Оскверните Храм, трупами наполните его дворы, а затем идите дальше!» Они пошли дальше и начали убивать в городе.","8":"Они убивали, а я остался один. И простерся я ниц и воззвал: «О Господь Бог! Неужели Ты истребишь весь остаток Израиля, изливая Свой гнев на Иерусалим?»","9":"Он сказал мне: «Слишком велик грех народа Израилева и народа Иудина, слишком велик! Эта земля пропитана кровью, этот город полон преступлений, потому что они говорили: „Оставил Господь эту землю, Господь не видит\".","10":"Потому Я не пощажу их, не помилую. Я обращу дела их против них самих!»","11":"И тот, кто был одет в льняные одежды, с принадлежностями писца на поясе, сказал в ответ: «Я сделал все, что Ты повелел мне»."},"10":{"1":"И видел я: над сводом, что был распростерт над головами у херувимов, виднелись словно бы очертания трона из лазурита.","2":"Господь сказал тому, кто был облачен в льняные одежды: «Подойди и встань меж кругов, под херувимами, и набери полные пригоршни углей, что пылают меж херувимов, – и брось пылающие угли на этот город!» И я видел, как он подошел.","3":"Херувимы стояли с южной стороны от Храма, когда он подошел к ним, и облако окутывало внутренний двор.","4":"(После того, как Слава Господня поднялась с херувима и встала у порога Храма, весь Храм был окутан облаком, а двор был наполнен сиянием Славы Господней.)","5":"Гул крыльев херувимовых был слышен даже во внешнем дворе Храма, и был он подобен голосу Всемогущего, изрекающего слово Свое.","6":"Когда Он повелел тому, кто был облачен в льняные одежды: «Возьми огонь, что пылает меж кругов, меж херувимами», тот подошел и встал подле колеса.","7":"И один из херувимов протянул руку к огню, что пылал меж херувимами, и взял этот огонь, и наполнил им пригоршни того, кто был облачен в льняные одежды. Тот взял огонь и отошел.","8":"У херувимов под их крыльями виднелись подобия человеческих рук.","9":"Я видел четыре колеса подле херувимов – подле каждого херувима было по колесу – и выглядели эти колеса так, будто они из хризолита.","10":"Очертания всех четырех колес казались одинаковыми: будто внутри каждого колеса находилось еще одно.","11":"Когда херувимы двигались, они могли двигаться в любую из четырех сторон, им не надо было поворачиваться, когда они двигались. Туда, куда было обращено лицо, туда они и двигались; им не надо было поворачиваться, когда они двигались.","12":"Все их тело, спины, руки, крылья и колеса усеяны были глазами – все четыре их колеса.","13":"(Вот эти-то колеса голос, который я слышал, и называл «кругами».)","14":"Четыре лица были у каждого из них: одно – лицо херувима, другое – лицо человека, третье – лицо льва, четвертое – лицо орла.","15":"И херувимы – те самые существа, которых я видел у реки Кевар, – поднялись над землей.","16":"Когда двигались херувимы, возле них двигались и колеса – и когда, взмахнув крылами, херувимы поднимались над землей, колеса от них не отставали, но всегда находились подле них.","17":"Когда херувимы останавливались, останавливались и колеса, а когда херувимы поднимались, вместе с ними поднимались и колеса, ибо и в колесах был Дух существ.","18":"Слава Господня отошла от порога Храма и встала над херувимами.","19":"Херувимы взмахнули крылами и у меня на глазах поднялись над землей – и когда они удалялись, колеса были возле них. Херувимы остановились у восточных ворот Дома Господня, и Слава Бога Израилева пребывала над ними.","20":"Это были те самые существа, которых я видел в подножии Бога Израилева у реки Кевар, я их узнал – это были херувимы.","21":"У каждого было по четыре лица, у каждого – по четыре крыла, а под крыльями – очертания человеческих рук.","22":"И очертания их лиц были подобны тому, что я видел при реке Кевар, и каждый из них двигался вперед лицом."},"11":{"1":"Дух поднял меня и перенес к восточным воротам Дома Господня, обращенным на восток. И вот возле ворот – двадцать пять человек. Среди них я увидел вельмож – Яазанию, сына Аззура, и Пелатию, сына Бенаи .","2":"И Он сказал мне: «Человек! Вот люди, у которых на уме одно зло, чьи замыслы несут этому городу беду!","3":"Говорят они: „Нескоро еще строить дома! Этот город – котел, мы в нем – мясо!\"","4":"Поэтому произнеси против них пророчество, произнеси пророчество, человек!»","5":"Снизошел на меня Дух Господень и сказал мне: «Скажи: „Так говорит Господь: вот что говорите вы, сыны Израилевы, но Я знаю, что у вас на уме!","6":"В этом городе вы совершали убийство за убийством, улицы его вы наполнили трупами!","7":"Потому так говорит Господь Бог: этот город – котел, но мясо – это убитые, которыми вы наполнили город, а вас Я из города изгоню.","8":"Вы боитесь меча – вот Я и пошлю на вас меч, – говорит Господь Бог. –","9":"Я изгоню вас из города и отдам вас в руки чужеземцев, Я совершу суд над вами!","10":"От меча вы погибнете – Я совершу суд над вами у границ Израиля. И вы поймете, что Я – Господь!","11":"Этот город не станет для вас котлом, и вы не станете в нем мясом – у границ Израиля Я совершу суд над вами,","12":"и вы поймете, что Я – Господь! Ибо по предписаниям Моим вы не поступаете, по законам Моим не живете, а живете по законам народов окрестных\"».","13":"И только я произнес это пророчество, как Пелатия, сын Бенаи, упал замертво. Я простерся ниц и громко воззвал: «О Господь Бог! Ты истребляешь остаток Израиля!»","14":"И было мне слово Господа:","15":"«Человек! Твоим братьям, братьям и родственникам, всему народу Израилеву, говорят жители Иерусалима: „Вы теперь вдали от Господа – а эта земля нам отдана во владенье!\"","16":"Но скажи: „Так говорит Господь Бог: да, Я увел их далеко, к другим народам, да, рассеял по странам, но Я Сам на время стал для них Храмом в тех землях, куда они пришли\".","17":"И потому скажи: „Так говорит Господь Бог: Я соберу вас среди народов, верну вас из стран, по которым вы были рассеяны, и дам вам землю Израиля!","18":"Они вернутся туда и все мерзости этой земли, все ее гнусности вырвут из нее с корнем.","19":"Я дам им сердце единое, новый дух Я вложу в них! Я вырву из их груди сердце каменное и вложу сердце из живой плоти,","20":"чтобы по Моим повелениям они поступали, законы Мои строго соблюдали и исполняли. И тогда они будут Моим народом, Я буду их Богом!","21":"А тем, чье сердце обращено к гнусным мерзостям, Я воздам за дела их! – говорит Господь Бог\"».","22":"Херувимы взмахнули крыльями, колеса были возле херувимов, над ними была Слава Бога Израилева.","23":"И вознеслась Слава Господня из города и встала над горою, что к востоку от города.","24":"Дух поднял меня и понес – в этом видении от Духа Божьего – в Халдею, к переселенцам. И кончилось это видение.","25":"Я пересказал переселенцам все, что явил мне Господь."},"12":{"1":"И было мне слово Господа:","2":"«Человек! Ты живешь среди упрямого племени. Есть глаза у них, чтобы видеть, но они не видят, уши есть у них, чтобы слышать, но они не слышат, ибо они – упрямое племя!","3":"А ты, человек, собери дорожный мешок изгнанника и уходи среди бела дня, у всех на виду, уходи прочь из своего дома у всех на виду! Быть может, поймут они, это упрямое племя.","4":"Сложи вещи свои в дорожный мешок изгнанника и вынеси среди бела дня, у всех на виду. А вечером уходи у всех на виду, как уходят изгнанники.","5":"У всех на виду сделай пролом в стене и выноси через него свои вещи.","6":"У всех на виду взвали мешок на плечи и неси его в потемках. Лицо свое покрой и не будешь видеть эту землю, ибо Я делаю тебя знаком для народа Израилева».","7":"Я сделал все, что было мне приказано. Среди бела дня я вынес свои вещи, сложив их в дорожный мешок изгнанника, а вечером своими руками я сделал пролом в стене и понес мешок в потемках, у всех на виду, взвалив его на плечи.","8":"Утром было мне слово Господа:","9":"«Человек! Израильтяне, это упрямое племя, спрашивали у тебя: „Что ты делаешь?\"","10":"Ответь же им: „Так говорит Господь Бог: это – предсказание о судьбе правителя иерусалимского и всех израильтян, что там живут\".","11":"Скажи им: „Я – знак для вас. С ними будет то же самое, что сделал я: в изгнание и плен они уйдут!","12":"Правитель их в потемках взвалит мешок на плечи и понесет его. И проломят стену, чтобы вывести его. Лицо свое он покроет, и глаза его не увидят эту землю.","13":"Я наброшу на него Мою сеть, попадет он в Мои тенета. Я заставлю его идти в Вавилон, в страну халдеев – да только видеть ее он не будет! И там он умрет.","14":"Всех, кто вокруг него, помощников его и воинов, Я развею по ветру, буду гнать их мечом.","15":"И поймут они, что Я – Господь, когда рассею их среди народов, развею по странам.","16":"Но некоторых из них Я спасу от меча, от голода и мора, чтобы они поведали народам, среди которых будут жить, о всех своих былых мерзостях. И поймут они, что Я – Господь!\"»","17":"И было мне слово Господа:","18":"«Человек! Хлеб свой ешь, дрожа от ужаса, воду пей, трепеща от страха!","19":"Скажи народу этой земли: „Так говорит Господь Бог о жителях Иерусалима, о стране Израилевой: в страхе будут они есть хлеб свой, воду пить в ужасе, ибо опустеет страна, лишится своего изобилия – из-за беззакония жителей ее.","20":"Населенные города будут разрушены, земля станет пустыней, и поймете вы, что Я – Господь\"».","21":"И было мне слово Господа:","22":"«Человек! Что это за поговорка у вас, в стране Израилевой: „Идет время – и все видения обращаются в ничто\"?","23":"Потому скажи им: „Так говорит Господь Бог: Я уничтожу эту поговорку, не будут впредь в Израиле повторять ее!\" И скажи им так: „Пришло время – и все видения исполнятся!","24":"Не будет впредь ни одного пророчества ложного, ни одного предсказания пустого среди народа Израилева.","25":"Что бы ни сказал Я, Господь, – это и исполнится, и теперь уже без промедления. На вашем веку, упрямое племя, Я исполню слово, Мною сказанное! – говорит Господь Бог\"».","26":"И было мне слово Господа:","27":"«Человек! Вот, говорят израильтяне: „Видения, о которых он рассказывает, сбудутся спустя многие годы, он пророчествует о временах далеких\".","28":"Потому скажи им: „Так говорит Господь Бог: ныне не будет отсрочки Моим словам. Что Я скажу, то и исполнится, – говорит Господь Бог\"»."},"13":{"1":"И было мне слово Господа:","2":"«Человек! Произнеси пророчество против пророков Израиля, которые собственные вымыслы выдают за пророчества, скажи им: „Слушайте слово Господа!","3":"Так говорит Господь: горе никчемным пророкам! По собственной прихоти они поступают, а не по пророческому видению!","4":"Стали пророки твои, Израиль, – словно шакалы среди развалин!","5":"Вы не шли к проломам в стене, не возводили вокруг дома Израилева такой ограды, которая устояла бы в битве, когда настанет День Господень!","6":"Видения их – тщета, предсказания – ложь! Говорят они:, сказал Господь, но Господь не посылал их! И они ждут, что исполнится слово?!","7":"Видения, которые вы видите, – тщета; предсказания, которые вы возвещаете, – ложь. Говорите вы:, сказал Господь, хотя Я вам ничего не говорил.","8":"Потому так говорит Господь Бог: вы говорили пустые слова и видели лживые видения, вот за это Я иду на вас, – говорит Господь Бог. –","9":"Обрушится Моя рука на пророков, на провидцев – обманщиков, на предсказателей лживых! Не будет их в собрании Моего народа, не будут они вписаны в список сынов Израилевых и в страну Израиля не войдут. И поймете вы, что Я – Господь Бог!","10":"Ведь они сбили с пути Мой народ, говоря, мир', хотя нет мира! Мой народ строит непрочную стену, а они ее покрывают побелкой!\"","11":"Скажи тем, кто ее покрывает побелкой: „Эта стена упадет! Пойдет проливной ливень, – вы, ледяные градины, сыпьтесь! – налетит ураганный ветер,","12":"и стена рухнет. И тогда призовут вас к ответу:, Как же так вы ее белили?'","13":"Так говорит Господь Бог: в ярости Моей Я пошлю ураганный ветер, в гневе Моем – ливень, ледяные градины – в ярости, и придет гибель.","14":"Я разрушу стену, которую вы покрывали побелкой, Я повергну ее на землю, сокрушу до основанья! И когда падет она, вы погибнете под ее обломками! И поймете вы, что Я – Господь!","15":"Когда Я сполна изолью Мою ярость на них, когда уничтожу и стену, и тех, кто покрывал ее побелкой, тогда Я скажу вам: Нет больше ни стены, ни тех, кто покрывал ее побелкой –","16":"пророков Израиля, что пророчествовали в Иерусалиме, предсказывали ему мир, хотя мира не было! – говорит Господь Бог\".","17":"Человек! Обрати свой взор против дочерей твоего народа, которые собственные вымыслы выдают за пророчества! Произнеси против них пророчество","18":"и скажи: „Так говорит Господь Бог: горе женщинам, что оплетают руки чародейными повязками, делают покрывала для головы – всевозможные амулеты, чтобы ловить души в сети! Вы ловите души Моего народа, а свои-то души – разве сможете уберечь от гибели?!","19":"За горсть ячменя, за ломоть хлеба вы бесславите Меня перед Моим народом, предрекаете смерть тем, кто не должен умереть, и возвещаете жизнь тем, кто не должен жить! Вы обманываете Мой народ, а он – внимает лжи!","20":"Потому так говорит Господь Бог: Я иду уничтожить ваши повязки, которыми вы ловите души, словно птиц! Я сорву эти повязки с ваших рук и выпущу души, пойманные вами, словно птицы.","21":"Я разорву ваши чародейные покрывала, Я избавлю Мой народ от вашей власти, больше не будет он вашей добычей. И поймете вы, что Я – Господь!","22":"Ибо невинных вы порицали понапрасну, хотя Я не хотел их порицать; нечестивого вы ободряли, чтобы он не сходил со своего злого пути и не спас свою жизнь.","23":"Потому не будете вы больше рассказывать о своих ложных видениях, не будете произносить предсказаний! Я избавлю Мой народ от вашей власти, и поймете вы, что Я – Господь!\"»"},"14":{"1":"Несколько старейшин Израилевых пришли ко мне и сели предо мной.","2":"И было мне слово Господа:","3":"«Человек! Этим людям нравятся идолы, на свою погибель они обратились ко греху! Неужели Я позволю им вопрошать Меня?","4":"Потому скажи им: „Так говорит Господь Бог: если кому-нибудь из народа Израилева нравятся идолы и он на свою погибель обратился ко греху, а потом пришел к пророку, то Я, Господь, отвечу такому человеку лишь обвинением – во всех его бесчисленных идолах!","5":"Я разоблачу тайные помыслы народа Израилева, который из-за идолов своих весь стал Мне чужим!\"","6":"Потому скажи народу Израилеву: „Так говорит Господь Бог: раскайтесь! От идолов своих отрекитесь, от мерзостей своих отвернитесь!","7":"Если кто-то из народа Израилева или из переселенцев, живущих среди израильтян, отвратился от Меня и ему стали милы идолы, если он обратился ко греху на свою погибель, – а потом пришел к пророку, чтобы через него вопрошать Меня… Я – Господь! Будет ему ответ от Меня:","8":"Против этого человека Я обращу Мой взор, Я сделаю его участь уроком и примером, Я отторгну его от Моего народа, чтобы поняли вы, что Я – Господь!","9":"И если пророк в помраченье осмелится вещать, это Я, Господь, помрачил его разум! Я обрушу на него Мою руку, Я уничтожу его в Моем народе, Израиле!","10":"Оба они виновны одинаково – и тот, кто вопрошал, и пророк. Оба понесут наказание за свой грех,","11":"чтобы народ Израилев больше не предавал Меня, не осквернял себя преступлениями своими, чтобы стал он Моим народом, а Я – его Богом, – говорит Господь\"».","12":"И было мне слово Господа:","13":"«Человек! Если какая-нибудь страна грешит предо Мною, совершает преступления, а Я за это простираю против нее Мою руку, отнимаю у нее хлеб, насылаю на нее голод, истребляю в ней всех людей и животных, –","14":"даже если бы в такой стране жили Ной, Даниил и Иов, то праведностью своей они смогли бы спасти лишь самих себя, – говорит Господь. –","15":"Если бы Я наслал на ту страну лютых зверей, чтобы убивали они сынов этой страны, чтобы стала она пустыней и чтоб никто по ней не ходил, боясь этих зверей,","16":"то даже эти три ее праведника, клянусь Самим Собою, – говорит Господь Бог, – не смогли бы спасти ни сыновей своих, ни дочерей. Только сами они спаслись бы, а страна превратилась бы в пустыню.","17":"Или если бы Я послал на ту страну меч и приказал ему: „Меч, пройди по этой стране, Я уничтожу здесь всех людей и животных!\",","18":"то даже эти три ее праведника, клянусь Самим Собою, – говорит Господь Бог, – не смогли бы спасти ни сыновей своих, ни дочерей, а только самих себя.","19":"Или если бы Я послал на ту страну мор, излил на нее Мою ярость кровавым потоком, истребляя и людей, и животных,","20":"то даже Ной, Даниил и Иов, живущие в той стране, клянусь Самим Собою, – говорит Господь Бог, – не смогли бы спасти ни сына своего, ни дочери, а смогли бы своей праведностью спасти лишь самих себя.","21":"Так говорит Господь Бог: вот, все эти четыре лютые кары Я насылаю на Иерусалим – голод, меч, лютых зверей и мор, – чтобы истребить там и людей и животных.","22":"И все же уцелеют некоторые из сыновей и дочерей Иерусалима и будут уведены оттуда. Придут они к вам, и вы увидите поступки их и дела. И тогда вы перестанете сокрушаться о том несчастье, которое Я послал Иерусалиму, обо всем, что Я послал ему.","23":"Они принесут вам утешение… ибо, видя поступки их и дела, вы поймете – недаром Я сделал все, что Я сделал с Иерусалимом, – говорит Господь Бог»."},"15":{"1":"И было мне слово Господа:","2":"«Человек! Разве древесина виноградной лозы лучше, чем древесина лесных кустарников?","3":"Разве годится она на что-нибудь полезное? Даже крючка из нее не сделаешь, чтобы повесить на него посуду!","4":"Бросают ее в огонь. Вот обгорела она с обоих концов, уже и середина обуглилась, какая же теперь от нее может быть польза?","5":"Когда была она цела – ни на что не годилась. Тем более – на что теперь она сгодится, когда огонь пожирает ее и вся она обуглилась?","6":"Потому так говорит Господь Бог: как виноградную лозу среди деревьев лесных Я обрекаю быть пищей огню, так же Я поступлю и с жителями Иерусалима!","7":"Я обращу против них Мой взор. Если из огня вырвутся – в полымя попадут! Поймете вы, что Я – Господь, когда против них Я обращу Мой взор.","8":"Я сделаю эту землю пустыней, ибо все они совершали преступления, – говорит Господь Бог»."},"16":{"1":"И было мне слово Господа:","2":"«Человек! Поведай Иерусалиму о мерзостях его!","3":"Скажи: „Так говорит Господь Бог Иерусалиму, столице: корень твой, родина твоя – страна ханаанеев, отец твой – аморей, а мать – хеттянка.","4":"Когда ты родилась, пуповину твою не обрезали, водой тебя не обмыли, не очистили, не обтерли тебя солью, не запеленали.","5":"Никто над тобой не сжалился и ничего этого не сделал для тебя – никто тебя не пожалел. Когда ты родилась, тебя отвергли с брезгливостью и бросили в чистом поле.","6":"Я проходил мимо и взглянул на тебя, брошенную под ноги прохожим, всю окровавленную, и сказал тебе, окровавленной:, Ты будешь жить!' Я сказал тебе, окровавленной:, Ты будешь жить!'","7":"И стала ты у Меня расти, как цветок в поле. Ты выросла, набралась сил и расцвела: поднялись груди, выросли волосы. Ты была нагой, ничем не прикрытой.","8":"Я проходил мимо, Я взглянул на тебя и увидел, что настала для тебя пора любви. Я распростер над тобою полы Моей одежды, покрыл твою наготу. Я поклялся тебе, Я заключил с тобой договор о верности, – говорит Господь Бог, – и ты стала Моей.","9":"Я омыл тебя водою, смыл с тебя твою кровь, умастил тебя оливковым маслом.","10":"Я одел тебя в узорчатые одежды, обул тебя в сандалии из тонко выделанной кожи, повязал твою голову тончайшим льном и покрыл лучшей тканью.","11":"Я украсил тебя прекрасными украшениями, Я надел тебе на руки браслеты и на шею – ожерелье.","12":"Кольцом Я украсил твой нос, серьгами – уши и великолепный венец возложил тебе на голову.","13":"Золотом и серебром ты была украшена, одета в тончайший лен, лучшие ткани, узорчатые одежды. И был у тебя хлеб из пшеничной муки, мед и оливковое масло. Ты стала прекрасна, достойна звания царицы.","14":"И прославилась ты среди народов своей красотою: ведь Мое великолепие, которым Я одарил тебя, сделало твою красоту совершенной, – говорит Господь Бог.","15":"Но ты возгордилась из-за своей красоты, ты славу свою поставила на службу распутству. Ты отдавалась всякому прохожему.","16":"Ты взяла свои покрывала и приготовила себе разукрашенные капища, чтобы там предаваться разврату – непотребство невиданное!","17":"Ты взяла украшения, которые Я подарил тебе, из Моего золота, Моего серебра, и сделала себе изваяния мужские, и распутничала с ними.","18":"Ты взяла свои узорчатые одежды и облачила в них эти изваяния. Мое масло и Мои благовония ты отдавала им.","19":"И пищу, которую Я даровал тебе, – пшеничную муку, масло и мед, которыми Я питал тебя, – ты приносила им в жертвы, – говорит Господь Бог. –","20":"И ты брала сыновей и дочерей, которых ты родила Мне, и приносила их в жертву этим идолам, на съедение. Мало тебе было распутства твоего –","21":"ты и детей Моих отдавала на заклание, приносила их в жертву этим идолам!","22":"Совершала ты все эти мерзости, распутничала – и забыла о своей юности, когда ты, нагая, ничем не прикрытая, валялась окровавленная под ногами у прохожих.","23":"За все твои злодеяния – горе тебе, горе! – говорит Господь Бог. –","24":"Ты воздвигла себе помосты, сделала себе возвышения на каждой площади.","25":"На каждом перекрестке ты построила себе возвышения и осквернила свою красоту. Ты раскидывала ноги перед каждым прохожим, предавалась разврату безудержно.","26":"Ты отдавалась египтянам, соседям твоим, с их здоровенной плотью. Своим безудержным распутством ты привела Меня в ярость.","27":"И тогда Я занес над тобой Мою руку, и долю твою сделал скудной, и отдал тебя на произвол врагам, – на произвол дочерей филистимских, даже им были противны твои мерзости.","28":"А ты распутничала с ассирийцами, не зная насыщения: распутничала с ними и не насыщалась!","29":"Распутничала ты безудержно со страной торгашей – Халдеей, но и этим ты не насытилась.","30":"Как сгораешь ты от желания, – говорит Господь, – ты ведешь себя, как проститутка!","31":"Строишь ты помосты на всех перекрестках дорог, возвышения свои ставишь на каждой площади. Но ты даже хуже проститутки – ведь нет у тебя нужды в деньгах.","32":"Ты – потаскуха, которая изменяет мужу с другими!","33":"Проституткам платят, а ты сама платишь всем своим любовникам, подкупаешь их, чтобы отовсюду они к тебе приходили распутничать с тобою.","34":"Ты еще хуже проституток: не тебя упрашивали, а ты просила. Ты платила, а не тебе платили – ты еще хуже!","35":"Потому слушай, распутница, слово Господа!","36":"Так говорит Господь Бог: за то, что ты развратничала с любовниками твоими, с мерзкими твоими идолами, за то, что обнажала стыд свой, срам свой раскрывала, за кровь детей твоих, которых ты им отдавала, –","37":"за это Я соберу всех любовников твоих, с которыми ты наслаждалась любовью, вместе с теми, кого ты ненавидела, соберу их всех отовсюду против тебя и обнажу срам твой перед ними. Пусть смотрят на твой стыд.","38":"Я вынесу тебе приговор, какой положен неверным женам и убийцам. В ярости Моей и ревности Я обреку тебя на кровавую смерть!","39":"Я отдам тебя в руки врагов, они разрушат твои помосты, уничтожат возвышения. Они сорвут с тебя одежды, отнимут украшения и оставят тебя нагой и непокрытой.","40":"Соберется против тебя толпа – они побьют тебя камнями, порубят на куски мечами,","41":"дома твои сожгут. Они исполнят приговор над тобою, – а другие женщины будут смотреть. Я положу конец твоему распутству, и больше ты не будешь раздавать подарки.","42":"Лишь тогда будет утолен Мой гнев на тебя и Моя ревность утихнет, Я успокоюсь и пройдет Моя ярость.","43":"Позабыв дни юности своей, ты гневила Меня своими поступками, теперь Я отплачу тебе за все твои дела, – говорит Господь Бог. – Разве не совершала ты преступления да мерзости?!","44":"И говоря о тебе, будут вспоминать поговорку:, Какова мать – такова и дочь!'","45":"Ты – дочь своей матери, она тоже мужа и детей своих возненавидела. Ты – сестра своих сестер, они тоже мужей и детей своих ненавидели. Мать ваша хеттянка, отец – аморей.","46":"Сестра твоя старшая – Самария и ее дочери; она обитала к северу от тебя. Твоя меньшая сестра, что обитала к югу, – Содома и ее дочери.","47":"Разве не так же, как они, ты поступала? Разве не такие же мерзости ты совершала? Но мало того, ты стала поступать еще хуже, чем они!","48":"Клянусь Самим Собою, – говорит Господь Бог, – ни Содома, сестра твоя, ни дочери Содомы не совершали того, что совершала ты и твои дочери!","49":"Вот каков был грех Содомы, сестры твоей: были у нее и у дочерей ее величие, изобилие, благополучие и покой, но никто из них не помогал нищему и бедняку.","50":"Возгордились они и стали совершать мерзости предо Мною, и Я отверг их, когда это увидел.","51":"А Самария и половины грехов твоих не совершила, мерзостями своими ты ее превзошла. Ты совершала такие гнусности, что сестер твоих уже не в чем винить.","52":"Стыдись! Твои грехи еще отвратительнее, чем их грехи; твои сестры кажутся праведницами по сравнению с тобой. Стыдись, будь покрыта позором, твои сестры оказались праведнее тебя!","53":"Я переменю к лучшему их участь – и участь Содомы, сестры твоей, с ее дочерьми, и участь Самарии с ее дочерьми – а уж тогда, вместе с ними, переменю и твою участь,","54":"чтобы терпела ты за свои дела стыд и позор. Пусть это их утешает.","55":"И сестра твоя Содома, и дочери Содомы станут такими, какими были прежде, и сестра твоя Самария, и дочери Самарии станут такими, какими были прежде, – тогда и ты со своими дочерьми станешь такой, какой была прежде.","56":"Разве не судачила ты о Содоме, сестре твоей, во времена величия твоего,","57":"когда еще не был открыт на показ твой срам? А теперь глумятся над тобой дочери Эдома и все соседи их, и дочери филистимлян – поносят тебя отовсюду!","58":"Это кара тебе за твой разврат и мерзости, – говорит Господь.","59":"Так говорит Господь Бог: Я поступлю с тобою так, как ты заслужила: ты нарушила договор о верности, пренебрегла страшной клятвой.","60":"Но Я помню договор о верности, который заключил с тобою во дни твоей юности, и буду до конца соблюдать этот вечный договор с тобою.","61":"И ты вспомнишь о своих поступках и станет тебе стыдно, когда Я возьму сестер твоих старших и сестер твоих меньших и отдам их тебе в дочери (хотя это и не предусмотрено договором с тобою).","62":"Я буду соблюдать Мой договор с тобою, и поймешь ты, что Я – Господь.","63":"Вспомнишь ты, и станет тебе стыдно, не посмеешь впредь и рта раскрыть от стыда, когда очищу тебя от всех твоих злодеяний, – говорит Господь Бог\"»."},"17":{"1":"И было мне слово Господа:","2":"«Человек! Загадай загадку, расскажи притчу народу Израилеву,","3":"скажи ему: „Так говорит Господь Бог: могучий орел с крыльями большими, с длинными крыльями, с опереньем густым, разноцветным, прилетел на Ливан, схватил вершину кедра,","4":"верхушку кроны его сорвал. И отнес ее в страну торгашей, в городе купцов оставил.","5":"Взял он семя этой земли и посадил на поле, к полноводному потоку принес, посадил среди сочной травы.","6":"Выросла лоза виноградная, раскидистая, невысокая. Ветви ее к нему тянулись, корни вниз уходили. Выросла лоза виноградная, и раскинула ветви, дала побеги.","7":"Был другой могучий орел, с крыльями большими, с опереньем густым. И лоза корнями к нему потянулась, ветви к нему простерла из сада, где была посажена, – хотела, чтобы он ее напоил водою.","8":"На хорошем поле, у полноводного потока была она посажена, чтобы пускать побеги, чтобы приносить плоды и быть виноградником великолепным\".","9":"Скажи: „Так говорит Господь Бог: что может ждать ее? Вырвут корни ее, оборвут гроздья, и все листья на ветвях ее засохнут! Засохнет она, и не нужно будет ни большой силы, ни многочисленного войска, чтобы вырвать ее с корнем!","10":"Пусть даже она укоренилась ныне, что может ждать ее? Налетит на нее восточный ветер, и она засохнет. В саду, где прижилась, – засохнет она!\"»","11":"И было мне слово Господа:","12":"«Спроси же у этого упрямого племени: „Понимаете ли вы, о чем это?\" Скажи им: „Царь вавилонский пришел в Иерусалим, взял в плен царя и вельмож иерусалимских и увел к себе в Вавилон.","13":"Он выбрал человека царского рода, заключил с ним договор о верности, скрепленный страшной клятвой. И всех вождей страны он взял в плен,","14":"чтобы царство это стало покорным, чтобы не возносилось, чтобы твердо соблю – дало договор о верности.","15":"Но восстал этот человек против вавилонского царя, отправил послов в Египет, чтобы получить оттуда лошадей и многочисленное войско. Что может ждать его теперь? Разве уцелеет тот, кто совершил такое? Он нарушил договор – неужели будет ему спасение?","16":"Клянусь Самим Собою, – говорит Господь Бог, – он умрет в плену у того царя, который возвел его на престол, в плену у того, кому дал клятву – и пренебрег ею, с кем заключил договор – и нарушил его. Он умрет в Вавилоне!","17":"И фараон со всей своей великой силой, многочисленным войском не поможет ему на этой войне, когда будет насыпан вал и воздвигнуты осадные сооружения, и люди будут гибнуть один за другим.","18":"Он пренебрег клятвой, нарушил договор. Он давал обещание быть верным – и вот что сделал! Нет ему спасения!","19":"Потому так говорит Господь Бог: клянусь Собою! Он презрел страшную клятву, данную предо Мною, нарушил договор, который заключал предо Мной, и за это Я обрушу на его голову все проклятья этого договора.","20":"Я наброшу на него Мою сеть, попадет он в Мои тенета. Уведу его в Вавилон, там Я буду его судить за преступленья его предо Мною.","21":"И лучшие воины из его войска падут от меча, а кто выживет, будут раскиданы по всем ветрам. И поймете вы, что это Я, Господь, так судил.","22":"Так говорит Господь Бог: Я возьму самую верхушку кедра и посажу ее в землю. Нежную ветвь из его кроны Я сорву и посажу ее. На горе великой, вознесенной,","23":"на высокой горе Израилевой Я посажу ее! Она даст побеги, принесет плоды и станет могучим кедром. Птицы крылатые будут обитать на нем, в тени ветвей его будут жить.","24":"И все деревья земные поймут, что Я, Господь, унизил дерево высокое и возвысил дерево низкое, что по воле Моей цветущее дерево засохло, а дерево сухое дало побеги. Я – Господь. Так Я сказал и так Я сделаю!\"»"},"18":{"1":"И было мне слово Господа:","2":"«Что это за поговорку вы твердите в стране Израилевой: „Отцы ели кислый виноград, а зубы разболелись у сыновей\"?!","3":"Клянусь Самим Собою, – говорит Господь Бог, – не будут больше у вас, в Израиле, твердить эту поговорку.","4":"Все живущие – в Моей власти! И жизнь отца, и жизнь сына – в Моей власти! Кто согрешил – тот и умрет!","5":"Кто ни в чем не виновен, кто поступает праведно и честно,","6":"не участвует в трапезах на горах и не обращает свой взор к идолам народа Израилева, кто жену ближнего не оскверняет, к женщине в период ее нечистоты не прикасается,","7":"кто никого не притесняет, возвращает должнику залог, никого не обирает, дает хлеб голодному, одевает нагого,","8":"не отдает денег в рост и процентов не берет, не делает злых дел и вершит справедливый суд,","9":"кто живет по законам Моим, повеления Мои строго соблюдает и исполняет, кто поступает по правде, – тот оправдан и будет жить! – говорит Господь Бог.","10":"А если родной его сын – разбойник, если проливает он кровь и совершает такие дела,","11":"которых отец никогда не делал: участвует в трапезах на горах, жену ближнего оскверняет,","12":"бедняка и нищего угнетает, обирает, не возвращает залога, к идолам обращает взоры, творит мерзость,","13":"если отдает деньги в рост и берет проценты, – неужели он сохранит себе жизнь? Нет, не будет он жить! За все мерзости, им совершенные, он умрет, и сам будет виновен в своей смерти!","14":"А если родной его сын увидит грехи, которые совершает отец, увидит и не пойдет по его стопам:","15":"не станет участвовать в трапезах на горах, не будет обращать взор к идолам народа Израилева, не будет осквернять жену ближнего,","16":"не будет никого угнетать, брать залога и обирать, если даст хлеб голодному, оденет нагого,","17":"не станет обижать нищего, не будет отдавать деньги в рост и брать проценты, если будет он жить по Моим законам и соблюдать повеления Мои, то не умрет он за грехи отца своего! Он сохранит свою жизнь!","18":"Но его отец, притеснявший и обиравший брата, творивший недобрые дела среди соплеменников, – он умрет за свои грехи!","19":"Вы спрашиваете: „Почему сын не отвечает за грехи своего отца?\" Потому что поступал справедливо и праведно, все повеления Мои строго соблюдал и исполнял – вот он и сохранил свою жизнь!","20":"Лишь тот, кто согрешил, тот и умрет! Сын не будет отвечать за грехи отца, и отец не будет отвечать за грехи сына. Праведные дела зачтутся праведнику и злодеяния – злодею.","21":"Если злодей оставит свои прошлые грехи, будет строго соблюдать и исполнять все законы Мои, будет поступать справедливо и праведно, то он не умрет, но сохранит себе жизнь!","22":"Его прошлые грехи не припомнятся ему, а теперешние его праведные дела сохранят ему жизнь.","23":"Разве Я хочу смерти грешника? – говорит Господь Бог, – Я хочу, чтобы он оставил свой дурной путь и сохранил себе жизнь!","24":"И если праведник отступит от своей праведности и начнет делать зло, совершать мерзости, какие творят злодеи, разве сохранит он себе жизнь? Праведные дела, какие он совершал раньше, не зачтутся ему! За преступления, которые он совершает ныне, за грехи, которыми ныне грешит, – он умрет.","25":"Вы скажете: „Несправедлив суд Господа!\" Но послушай, народ Израилев! Разве Я сужу несправедливо? Это ваш суд несправедлив!","26":"Если праведник, оставив свою праведность и делая зло, умирает, то это он умирает за свои злодеяния.","27":"И если злодей отступит от своих злых дел и будет поступать справедливо и праведно, то он тем самым спасет себя от смерти.","28":"Если, одумавшись, оставит он свои прежние беззакония, – то не умрет, но сохранит себе жизнь!","29":"Народ Израилев скажет: „Несправедлив суд Господа!\" Разве Я сужу несправедливо, о народ Израилев? Это ваш суд несправедлив!","30":"Ибо каждого из вас, о народ Израилев, Я буду судить по делам его, – говорит Господь Бог. – Раскайтесь, оставьте грехи свои, чтобы они не погубили вас!","31":"Оставьте все свои прежние грехи и обретите сердце новое и дух новый! Зачем погибать тебе, народ Израилев?!","32":"Я не хочу ничьей смерти, – говорит Господь Бог, – раскайтесь и сохраните себе жизнь!»"},"19":{"1":"А ты оплачь вождей Израиля!","2":"Воистину, твоя мать – львица! Среди львов она жила, среди львов молодых львят своих растила!","3":"Одного из львят своих вскормила, молодым львом он стал, научился ловить добычу, людей пожирал.","4":"Услыхали о нем народы, в яму его поймали, крюками уволокли в Египет.","5":"Видит львица, что ждет его напрасно, что надежда ее погибла! И взяла она львенка другого, молодого льва вырастила.","6":"Среди львов он жил, молодым львом стал. Научился ловить добычу, людей пожирал.","7":"Крепости разрушал, опустошал города. Цепенела земля и все живое на ней от громкого его рыка!","8":"И напали на него народы, жители всех стран окрестных, сети против него раскинули, в яму поймали.","9":"Надели на него ошейник, крюками уволокли к царю Вавилона. Отвели его в крепость, чтобы рык его больше не раздавался с гор Израилевых!","10":"Твоя мать была – что лоза виноградная, посаженная у потоков полноводных. Плодовитой была и ветвистой – так вода ее орошала.","11":"Были ветви ее крепки, для жезла владык годились. Над чащей она возвышалась, была видна отовсюду, высокая и ветвистая.","12":"Но вырвана она во гневе, на землю брошена. Восточный ветер плоды ее высушил. Обломлены и погублены крепкие ее ветви, огонь пожрал их.","13":"И вот пересажена она в пустыню, на землю зноя и жажды.","14":"Огонь на ветвях ее вспыхнул и пожрал плоды ее. Больше не осталось у нее крепкой ветви, годной для жезла владык. Таков этот плач. И эти слова стали траурной песнью."},"20":{"1":"В седьмой год, в десятый день пятого месяца несколько человек из старейшин Израилевых пришли, чтобы вопросить Господа, и сели предо мною.","2":"И было мне слово Господа:","3":"«Человек! Скажи старейшинам Израилевым, передай им: „Так говорит Господь Бог: вы пришли вопросить Меня? Клянусь Самим Собою, не получите вы от Меня ответа! – говорит Господь Бог\".","4":"Призови их на суд, человек, призови их на суд! Поведай им о мерзостях отцов их!","5":"Скажи им: „Так говорит Господь Бог: когда Я избрал Израиль, когда дал клятву племени Иакова, – явившись им в Египте и скрепив эту клятву словами: Я, Господь, – Бог ваш! –","6":"Я поклялся им, что выведу их из Египта на землю, которую Я для них выбрал, на землю, текущую молоком и медом, прекраснейшую среди всех земель.","7":"Я сказал им:, Пусть каждый из вас оставит мерзости, к которым вы обращаете взоры! Не оскверняйте себя идолами египетскими! Я, Господь, – Бог ваш!'","8":"Но они восстали против Меня, не захотели Мне подчиниться. Никто из них не оставил мерзостей, к которым они обращали взоры, никто не оставил идолов египетских. И там, в Египте, Я хотел излить на них Мою ярость, сполна излить на них Мой гнев.","9":"Но Я этого не сделал – ради имени Моего, чтобы не было оно обесславлено перед народами, среди которых они жили, ибо на глазах у этих народов Я явился племени Иакова и обещал, что выведу их из Египта.","10":"И Я вывел их из Египта и привел в пустыню.","11":"Я поведал им предписания Мои, дал законы, несущие жизнь тому, кто соблюдает их.","12":"Я установил для них субботы Мои как знак договора со Мною, чтобы видно было, что Я, Господь, посвятил их Себе!","13":"Но восстал против Меня народ Израилев в пустыне. Повеления Мои они не исполняли, отвергли Мои законы, несущие жизнь тому, кто соблю – дает их, и субботы Мои осквернили. И там, в пустыне, Я хотел излить Мою ярость на них и истребить их.","14":"Но Я этого не сделал – ради имени Моего, чтобы не было оно обесславлено перед народами, на глазах у которых Я вывел племя Иакова из Египта.","15":"Там, в пустыне, Я поклялся, что не отведу их в землю, которую им предназначал, землю, текущую молоком и медом, прекраснейшую среди всех земель,","16":"за то что законы Мои они отвергли, повеления Мои не исполняли, субботы Мои осквернили и всей душой обратились к идолам.","17":"Но Я пощадил племя Иакова, не уничтожил их, не стал истреблять их в пустыне.","18":"Там, в пустыне, Я сказал их сыновьям:, По обычаям отцов ваших не живите, законы их не соблюдайте, идолами их не оскверняйтесь!","19":"Я, Господь, – Бог ваш! По Моим повелениям живите, Мои законы строго соблюдайте и исполняйте.","20":"Чтите святость Моих суббот, и пусть будут они знаком договора между Мной и вами, чтобы видно было, что Я, Господь, – Бог ваш!'","21":"Но их сыновья тоже восстали против Меня, по повелениям Моим не жили, не соблюдали и не исполняли Мои законы, несущие жизнь тому, кто их соблюдает, и субботы Мои осквернили. И там, в пустыне, Я хотел излить на них Мою ярость, сполна излить на них Мой гнев.","22":"Но вновь удержал Я Мою руку – и не сделал этого, ради имени Моего, чтобы не было оно обесславлено перед народами, на глазах у которых Я вывел их из Египта.","23":"Там, в пустыне, Я поклялся им, что рассею их среди народов, разметаю по странам,","24":"за то, что законы Мои они не исполняли, повеления отвергли, субботы Мои оскверни-ли и обратили взоры к идолам, которым поклонялись их отцы.","25":"Тогда и Я дал им повеления пагубные, законы, несущие гибель.","26":"Я заставил их оскверняться собственными приношениями – приносить в жертву первый плод всякого материнского чрева. Я это сделал, чтобы обречь их на гибель, – чтобы поняли они, что Я – Господь!\"","27":"Потому скажи народу Израилеву, человек, скажи им: „Так говорит Господь Бог: вот как еще оскорбляли Меня ваши отцы, вот какое еще кощунство они совершали.","28":"Когда Я привел их на землю, которую поклялся отдать им, они – стоило им лишь увидеть высокий холм или дерево ветвистое – они приносили там свои жертвы, ненавистные Мне приношения. Они возносили там благоуханный дым жертв и возливали свои возлияния\".","29":"„Что это за капище, куда вы идете?!\" – сказал Я им. (С тех пор и доныне капища зовутся „капищами\".)","30":"Потому скажи народу Израилеву: „Так говорит Господь Бог: вы оскверняете себя, поступая так же, как поступали ваши отцы. С мерзкими их идолами вы распутничаете!","31":"Доныне вы в угоду вашим идолам оскверняете себя: приносите им приношения, сжигаете в жертву собственных детей! Так неужели Я стану отвечать тебе, народ Израилев, когда ты Меня вопрошаешь? Клянусь Самим Собою, – говорит Господь Бог, – не будет вам от Меня никакого ответа!","32":"Но не бывать никогда тому, о чем вы мечтаете! Ведь вы говорите:, Станем как другие народы, как племена чужие, будем поклоняться деревяшкам и камням!'","33":"Нет, клянусь Самим Собою, царствовать над Вами буду Я, – говорит Господь Бог, – буду править рукой Моей могучей, десницей простертой, в ярости и гневе!","34":"Я выведу вас из земель чужих народов, соберу из стран, по которым вы рассеяны, – рукой Моей могучей, десницей простертой, в ярости и гневе!","35":"Я приведу вас в пустыню во владениях чужих народов и буду судиться там с вами лицом к лицу.","36":"Как судился Я с вашими отцами в пустыне египетской, так и с вами Я буду судиться! – говорит Господь Бог. –","37":"Я проведу вас под жезлом пастуха и наложу на вас узы договора о верности.","38":"Я очищу вас от мятежников, от тех, кто Мне не повинуется. Я уведу их из страны, где они живут, но на землю Израиля они не ступят! И тогда поймете вы, что Я – Господь!","39":"О народ Израилев! – говорит Господь Бог, – ступай к своим идолам, служи им и дальше, если Мне ты не повинуешься! Но имени Моего святого больше не смейте бесславить изваяниями и такими приношениями!","40":"Лишь на Моей святой горе, на высокой горе Израилевой, – говорит Господь Бог, – там должен поклоняться Мне весь народ Израилев, весь, сколько ни есть его на земле. Там он будет Мне угоден. Туда Я потребую приносить ваши дары, ваши первины – все ваши святые жертвы.","41":"Там вы будете Мне угодны, словно благоуханный дым жертв, когда выведу вас от народов, соберу из стран, где вы были рассеяны, и Я явлю Мою святость – через то, что Я совершу с вами на глазах у народов.","42":"Поймете вы, что Я – Господь, когда приведу вас в землю Израиля, в страну, которую обещал отдать вашим отцам.","43":"И там вы вспомните о всех ваших делах, о всех поступках ваших, которыми вы осквернялись, и станете сами себе отвратительны из-за мерзостей, которые вы совершили прежде.","44":"И тогда поймете вы, что Я – Господь, когда Я поступлю с вами так, как подобает имени Моему, – а не так, как вы того заслужили своими злодеяниями и мерзостями, – говорит Господь Бог\"».","45":"И было мне слово Господа:","46":"«Человек! Обрати свой взор против Темана, произнеси речь против Дарома, изреки пророчество против лесов и пустошей Негева.","47":"Скажи лесам Негева: „Слушайте слово Господа! Так говорит Господь Бог: Я разожгу в вас огонь, и он уничтожит все ваши деревья – и зеленеющие, и сухие. Не погаснет бушующее пламя, все сгорит в нем от юга и до севера.","48":"И поймут все живущие, что Я, Господь, разжег этот огонь негаснущий\"».","49":"…Я воззвал: «О Господь Бог! Эти люди говорят обо мне: „Он басни рассказывает!\"»"},"21":{"1":"И было мне слово Господа:","2":"«Человек! Обрати свой взор против Иерусалима, произнеси речь против Святилища, изреки пророчество против страны Израилевой!","3":"Скажи стране Израилевой: „Так говорит Господь: Я иду на тебя! Я обнажаю Свой меч, чтобы уничтожить у тебя и правых и виноватых.","4":"Я уничтожу у тебя и правых и виноватых – Мой обнаженный меч обрушится на все живое, от юга и до севера.","5":"И поймут все живущие, что Я, Господь, извлек Свой меч из ножен, – и обратно в ножны он уже не вернется.","6":"А ты, человек, плачь! Бей по бедрам себя в горе! Плачь у всех на глазах!","7":"И когда спросят тебя:, Отчего ты плачешь?', ответь:, Из-за страшной вести, что сейчас придет!' У каждого сердце истает как воск, опустятся руки, душа оцепенеет, жидкими станут колени! Вот что грядет, вот что сбывается, – говорит Господь Бог\"».","8":"И было мне слово Господа:","9":"«Человек! Произнеси пророчество, скажи: „Так говорит Господь! Меч, меч заострен, заточен до блеска!","10":"Он заострен для бойни, наточен – чтобы сверкал, как молния! (Я испытаю жезл сына Моего, – что надменно взирает на деревья!)","11":"Он будет наточен и в руку взят. Заострен этот меч, вот он – заточен, в руку убийцы вложен!","12":"Кричи, рыдай, человек! Ибо меч занесен над Моим народом, над всеми вождями Израиля. Добычей меча они станут вместе с Моим народом! Потому бей себя по бедрам!","13":"(Испытанье настало – и что же? Не будет надменного жезла! – говорит Господь Бог.)\"","14":"А ты, человек, произнеси пророчество, бей рукой об руку! Пусть дважды пройдется меч по телам, пусть трижды пройдется меч смертоносный. Этот меч – для великой бойни, меч пронзающий!","15":"Пусть трепещут сердца, пусть больше будет убитых! Над каждым их городом Я занес смертоносный меч! О горе! Он создан, чтобы разить, как молния, заточен он для резни!","16":"Меч! Острие свое обрати направо, рази налево – всюду, куда ты направлен будешь!","17":"А Я буду бить рука об руку, сполна изолью Мою ярость. Так говорю Я, Господь!»","18":"И было мне слово Господа:","19":"«Человек, проложи две дороги для меча царя вавилонского. Из одного и того же места начинаются обе. И поставь знак: на перекрестке дорог, ведущих в эти города, – там поставь этот знак.","20":"Проложи дорогу, по которой меч пойдет в Равву Аммонитскую, и дорогу, по которой пойдет он в Иудею, к укреплениям Иерусалима.","21":"Ибо вот стоит царь вавилонский на распутье, собирается совершить гадание: какой дорогой идти. Трясет он стрелы, вопрошает терафимов и рассматривает печень.","22":"И правая его рука вытянула жребий, указывающий на Иерусалим: там будут стоять тараны, там раздастся команда на штурм, там будет греметь боевой клич! Возле ворот установят тараны, насыплют вал и воздвигнут осадные сооружения.","23":"…А они, там, могут считать, что все это гадание – выдумки. Но они ведь давали страшные клятвы – и потому будут они изобличены, будут схвачены за руку.","24":"Ибо так говорит Господь Бог: вы сами себя изобличили! Преступления ваши открылись, и стали видны все ваши грехи, – потому вы будете изобличены, будете схвачены за руку!","25":"О нечестивый злодей, вождь Израиля, чей день настал, время расплаты пришло!","26":"Так говорит тебе Господь Бог: сними тюрбан, брось венец! Все переменится: низкое станет высоким, высокое – низким.","27":"Разрушу, разрушу, разрушу этот город, будто его и не было! И будет так, пока не придет тот, кому он принадлежит по праву. И тогда Я вручу ему этот город.","28":"А ты, человек, произнеси пророчество, скажи: „Так говорит Господь Бог о глумливых сынах Аммоновых\". Скажи: „О меч, меч, обнаженный для бойни, наточенный, чтобы губить, чтобы разить, как молния!","29":"Пусть пророчества о тебе – пустые, пусть предсказания о тебе – ложные, все же ты обрушишься на шею нечестивых злодеев, когда их день настанет, время расплаты придет!","30":"Но вернись в ножны! В месте, где ты появился на свет, на земле, откуда ты родом, Я устрою суд над тобою!","31":"Изолью на тебя Мой гнев, сожгу огнем Моей ярости. Отдам тебя в руки людей жестоких, чье ремесло – убийство!","32":"Огонь тебя поглотит, кровь твоя по земле разольется, и даже памяти о тебе не останется! Так говорю Я, Господь\"»."},"22":{"1":"И было мне слово Господа:","2":"«Ты, человек, готов ли судить кровавый город? Скажи ему о всех его мерзостях!","3":"Скажи: „Так говорит Господь Бог: о город, проливающий кровь себе на погибель, делающий идолов, чтобы ими оскверняться!","4":"Виновный в кровопролитии, оскверненный идолами, ты сам приблизил свой срок, годы твои сочтены. Я отдам тебя на поругание народам, на поношение всем странам.","5":"И далекие страны, и соседние – все будут глумиться над тобою, город, осквернивший свое имя, город мятежный!","6":"Вожди Израиля только то и делали здесь, что проливали кровь, кто сколько мог.","7":"Мать и отца здесь ни во что не ставят, переселенцев притесняют, сироту и вдову обижают.","8":"Святыни Мои ты презираешь и субботы Мои оскверняешь.","9":"Полон ты клеветниками – виновниками кровопролитий. Здесь совершаются трапезы на горах и творятся мерзости.","10":"Здесь срам отца своего открывают, совокупляются с женщиной во время нечистоты ее.","11":"Один совершает гнусность с женой ближнего своего, другой оскверняет сноху, третий родную сестру, дочь отца своего, насилует!","12":"За взятки кровь проливают. Вы даете деньги в рост и берете процен – ты, наживаетесь, притесняя ближнего! Ты, столица, забыла Меня, – говорит Господь Бог. –","13":"Смотри, как Я ударяю рука об руку, видя, что ты наживаешься насилием и проливаешь кровь.","14":"А хватит ли тебе смелости и силы в те дни, которые Я тебе уготовил? Я – Господь! Так Я сказал, и так Я сделаю!","15":"Я рассею тебя среди народов, развею по странам, положу конец твоей скверне.","16":"Будешь ты опозорена на глазах у народов и поймешь, что Я – Господь\"».","17":"И было мне слово Господа:","18":"«Человек! Народ Израилев стал для Меня шлаком. Все они в горниле либо медь, либо олово, либо свинец. Серебро стало шлаком.","19":"Ибо так говорит Господь Бог: все вы – только шлак. Поэтому Я соберу вас в Иерусалим –","20":"как складывают в горниле серебро, медь, железо, свинец и олово и раздувают огонь, чтобы плавить, так и Я соберу вас в ярости Моей и гневе, сложу вас всех вместе и переплавлю.","21":"Я соберу вас и дуну на вас огнем Моей ярости, и вы переплавитесь в нем!","22":"Как плавится серебро в горниле, так и вы будете переплавлены в Иерусалиме и поймете, что это Я, Господь, изливаю на вас Мою ярость».","23":"И было мне слово Господа:","24":"«Человек! Скажи этой стране: ты – страна, не орошенная дождями и ливнями, ибо пал на тебя день гнева!","25":"Вожди ее – словно львы, терзающие добычу. Пожирают они людей, отнимают их имущество и достояние, из-за них страна полна вдов.","26":"Священники ее попирают Мой Закон, святыни Мои оскверняют. Не отделяют они священное от несвященного, не делают различия между нечистым и чистым. Субботы Мои они презирают, Меня не чтят.","27":"Вельможи ее – словно волки, терзающие добычу. Кровь они проливают, людей губят ради своей наживы.","28":"А пророки ее – все обеляют. Видения их – обман, предсказания их – ложь. Говорят они: „Так говорит Господь Бог\", хотя Господь не говорил этого.","29":"И люди этой страны – притеснители и грабители. Притесняют они бедняка и нищего, несправедливо угнетают переселенцев.","30":"Я искал среди них человека, который смог бы воздвигнуть крепостную стену, который встал бы в проломе стены предо Мною, защищая эту страну от уничтожения, – но не нашел!","31":"Потому изолью на них Мой гнев, в огне Моей ярости уничтожу их, воздам им за их поступки, – говорит Господь Бог»."},"23":{"1":"И было мне слово Господа:","2":"«Человек! Жили две женщины, дочери одной матери.","3":"С молодости они предались разврату, распутничали в Египте. Там мяли их груди и девичьи их соски.","4":"Старшую сестру звали Огола, другую – Оголива. Я взял их в жены, и они рожали сыновей и дочерей (имя Огола означает – Самария, а Оголива – Иерусалим).","5":"Но изменила Мне Огола, стала развратничать, утолять свою похоть с любовниками, витязями ассирийскими,","6":"одетыми в пурпур, с наместниками и полководцами. Все они – прекрасные юноши, наездники и возницы.","7":"Расточала она ласки свои перед знатными сыновьями Ассирии и осквернялась идолами всех тех, к кому пылала страстью.","8":"Не переставала она развратничать со времен Египта, когда египтяне ложились с ней, еще юной, мяли девичьи ее соски и изливали на нее свою похоть.","9":"И Я отдал ее в руки любовников ее, в руки ассирийцев, к которым она пылала такой страстью.","10":"Они обнажили срам ее, взяли в плен сыновей ее и дочерей, а саму ее – изрубили мечами. Они совершили справедливую казнь. И стала ее судьба предостережением для всех женщин.","11":"Видела все это сестра ее Оголива, но она была еще порочнее и распутнее, чем сестра. Своим развратом она превзошла разврат сестры.","12":"С ассирийцами она утоляла свою похоть, с наместниками и полководцами, с витязями в полном боевом облачении. Все они – наездники и возницы, юноши прекрасные.","13":"И увидел Я, что и она осквернилась, что обе они пошли по одной дороге.","14":"А Оголива продолжала свое распутство. Увидала она мужчин, запечатленных на рельефах, изображения халдеев, раскрашенные алой краской.","15":"Опоясанные поясами, с пышными тюрбанами на головах, с внешностью героев – так изображены были сыны Вавилона. Родина их Халдея.","16":"Лишь взглянула она на них – и воспылала страстью, и отправила послов к ним в Халдею.","17":"Пришли к ней сыновья Вавилона, на любовное ее ложе, осквернили ее похотью своей. Осквернялась она с ними, пока они ей не опротивели.","18":"Выставляла она на показ похоть свою, выставляла на показ срам свой. Потому она стала Мне омерзительна, как омерзительна была Мне ее сестра.","19":"Предавалась она безудержному разврату, вспомнив дни своей молодости, когда проституткой была в Египте.","20":"Утоляла свою страсть с любовниками, плоть которых – что у осла, и похоть – что у жеребцов.","21":"Так вернулась ты к распутству, которому предавалась в молодости, когда соски твоей молодой груди мяли в Египте.","22":"И потому, Оголива, так говорит Господь Бог: Я подниму против тебя любовников твоих, уже опостылевших тебе, и приведу их к тебе со всех сторон:","23":"сынов Вавилона и всех халдеев, из Пекода, из Шоа и Коа, а вместе с ними всех ассирийцев. Все они – юноши прекрасные, наместники и полководцы, опытные воины и вельможи, наездники и возницы.","24":"И придут они к тебе с боевыми колесницами, со множеством воинов. С броней, щитами и шлемами нападут они на тебя со всех сторон. Я отдам тебя им на суд, они будут судить тебя, как захотят.","25":"Я заставлю тебя изведать Мою ревность! Они поступят с тобою люто: отрежут тебе нос и уши! А что останется – будет мечом изрублено! Сыновей и дочерей твоих они в плен возьмут. А все, что уцелеет, огонь поглотит.","26":"Сорвут с тебя твои одежды, возьмут твои украшения.","27":"Я положу конец твоему распутству, разврату твоему, который начался еще в Египте, и больше не будешь ты обращать свои взоры к Египту – больше ты о нем и не вспомнишь.","28":"Ибо так говорит Господь Бог: Я отдаю тебя в руки тех, кто тебе опротивел и опостылел.","29":"Они поступят с тобой жестоко. Все, над чем ты трудилась, отнимут, оставят тебя нагой и непокрытой. Обнажится похотливый твой срам, и разврат твой, и распутство.","30":"Вот что будет сделано с тобой за твое распутство с народами – за то, что ты осквернялась их идолами.","31":"Ты пошла по той же дороге, что и твоя сестра, потому Я вкладываю тебе в руки ее чашу.","32":"Так говорит Господь: и будешь ты пить ту же чашу, что твоя сестра испила, – чашу глубокую и широкую, чашу полную – и унижена ты будешь и опозорена.","33":"Будешь ты пьяна горем: это чаша ужаса и разрушения, это чаша сестры твоей, Самарии.","34":"И ты выпьешь ее, до дна осушишь – и разобьешь ее вдребезги и грудь себе расцарапаешь. Так Я сказал, – говорит Господь Бог.","35":"Потому так говорит Господь Бог: ты забыла Меня и отвернулась от Меня – так отвечай же за распутство свое и разврат!»","36":"И сказал мне Господь: «Человек! Готов ли ты судить Оголу и Оголиву и говорить им о всех мерзостях их?","37":"Развратничали они, и на их руках – кровь. С идолами своими они развратничали и детей, которых Мне рожали, отдавали идолам на съедение.","38":"И вот еще в чем они виновны предо Мною: святилище Мое они осквернили и субботы Мои не соблюдали.","39":"Зарежут собственных детей в жертву идолам – и в тот же день приходят в святилище Мое, оскверняя его! Вот что делали они в доме Моем!","40":"Отправляли они послов в далекие страны, чтобы пришли оттуда мужчины. Когда те приходили, ты для них омывалась, подводила глаза сурьмою, наряжалась в свои украшения.","41":"Ты садилась на прекрасное ложе, пред накрытым столом, – и на этот стол ты ставила Мои благовония, Мои благовонные масла.","42":"И раздавались там крики беззаботного сборища, и для мужчин собравшихся несли вино из пустыни. Они украшали твои руки браслетами, голову твою – прекрасными венками».","43":"И сказал Я об этой потаскухе потрепанной: «Пусть, пусть теперь они развратничают с нею!»","44":"И забавлялись они с ней, словно с проституткой, – так забавлялись они с Оголой и Оголивой, с развратницами.","45":"Но будут мужчины судить их по справедливости – за разврат и кровопролитие, за то, что развратничали они и руки свои обагрили кровью.","46":"Ибо так говорит Господь Бог: «Созвать против них огромную толпу, пусть они задрожат от ужаса, пусть будут растерзаны!","47":"Пусть толпа побьет их камнями, пусть изрубит мечами, сыновей и дочерей их убьет, а дома их сожжет.","48":"Я положу конец распутству на этой земле, и будет это уроком для всех женщин, чтобы не развратничали они, подобно вам.","49":"Вы поплатитесь за свой разврат и за идолов ваших и поймете, что Я – Господь Бог»."},"24":{"1":"В девятый год, в десятый день десятого месяца было мне слово Господа:","2":"«Человек, запиши, что сегодня за день, запиши эту дату – в этот день Навуходоносор, царь Вавилона, осадил Иерусалим.","3":"И поведай упрямому племени притчу, скажи ему: „Так говорит Господь Бог: поставь котел, поставь и воду в него налей.","4":"Положи в него куски мяса, отборные части – голени и лопатки. Наполни его лучшими кусками мяса на кости,","5":"возьми для этого отборных овец. Разложи дрова под котлом, пусть кипит ключом вода, пока мясо с костями не разварятся!","6":"Так говорит Господь Бог: горе городу, полному кровопролитья! Горе котлу, покрытому накипью! Накипь от него не отходит! Кусок за куском, без разбора, выкидывай из него мясо!","7":"Этот город запятнан пролитой кровью. На голые камни он проливал ее – даже не на землю, чтобы потом присыпать.","8":"Чтобы разгорелась Моя ярость, чтобы свершилось отмщение, Я эту кровь выставил напоказ – на голых камнях, так что не скрыть ее.","9":"Потому так говорит Господь Бог: горе городу, полному кровопролитья! Я Сам разведу огромный костер!","10":"Дров добавь, разожги огонь, вывари мясо, приготовь варево, пусть кости распадутся.","11":"А потом поставь пустой котел на угли, чтобы медь его докрасна раскалилась, чтобы накипь выгорела и нечистота исчезла.","12":"Но напрасны все усилия! Не отойдет густая накипь, даже огонь не поможет!","13":"Омерзительна нечистота твоя! Сколько ни чистил Я тебя – ты все нечист. И не очиститься тебе, пока сполна не изольется ярость Моя.","14":"Так говорю Я, Господь! Срок пришел – и Я так сделаю, не остановлюсь, не пощажу, не помилую! За дела твои, за поступки твои будет суд над тобой, – говорит Господь Бог\"».","15":"И было мне слово Господа:","16":"«Человек! Я тебе посылаю беду – отниму у тебя радость твоих очей. Но ты не плачь, не рыдай, не лей слез!","17":"Стенай в молчании, не совершай погребального плача, тюрбана своего не снимай, не снимай сандалий, не покрывай уст и не ешь поминального хлеба».","18":"Утром того дня я проповедовал народу, а вечером – умерла моя жена. На следующий день я поступил так, как было мне велено.","19":"И стали люди спрашивать: «Объясни, как нам понимать то, что ты делаешь?»","20":"Я ответил им: «Мне было слово Господа,","21":"чтобы я сказал народу Израилеву: „Так говорит Господь Бог: Я отдам на поругание Мое святилище, гордость вашу и силу, радость очей ваших, самое дорогое для ваших душ. А сыновья ваши и дочери, которых вы оставили в городе, падут от меча!\"","22":"И вы поступите так же, как я сейчас, – вы не покроете своих уст, не будете есть поминального хлеба.","23":"Тюрбаны ваши останутся на ваших головах, сандалии – на ногах, вы не будете совершать плача, вы будете мучиться за свои грехи и стенать друг перед другом.","24":"Иезекииль – знак того, что ждет вас. Все, что он сейчас делает, то и вы будете делать, когда придет срок. И поймете вы, что Я – Господь Бог.","25":"А ты, человек, жди: когда Я отниму у них силу их, радость их и славу, отраду очей и самое дорогое для их душ, когда отниму сыновей их и дочерей,","26":"придет к тебе уцелевший беглец, чтобы рассказать тебе об этом.","27":"Когда он придет, уста твои откроются, ты будешь говорить и твое молчание закончится. Ты – знак того, что ждет их, и поймут они, что Я – Господь»."},"25":{"1":"И было мне слово Господа:","2":"«Человек! Обрати свой взор против аммонитян и произнеси против них пророчество.","3":"Скажи стране сынов Аммоновых: „Слушай слово Господа Бога! Так говорит Господь Бог: ты хохочешь, видя, как поругано Мое святилище, как опустошена земля Израилева, как народ Иудин отправляется в изгнание, –","4":"вот за это Я сделаю тебя добычей восточных племен. Они устроят на твоей земле свои стоянки, поставят свои шатры. Они будут есть твои плоды и будут пить твое молоко.","5":"Я превращу Равву в стойло для верблюдов, город сынов Аммоновых – в загон для овец. И поймете вы, что Я – Господь!","6":"Так говорит Господь Бог: ты глумишься и радуешься всей душою, глядя на землю Израилеву, хлопаешь в ладоши и топаешь ногами от злорадства, –","7":"вот за это Я обрушу на тебя Мою руку и отдам тебя народам на разграбленье. Я уничтожу тебя – и не будет больше такого народа! Я искореню тебя – и не будет больше такой страны! Я разрушу тебя, и ты поймешь, что Я – Господь!","8":"Так говорит Господь Бог: твердят Моав и Сеир:, Смотрите, народ Иудин – не лучше других народов!' –","9":"вот за это Я сделаю Моав беззащитным и отниму у него города, прекраснейшие города в его стране – Бет – Иешимот, Баал – Меон и Кирьятаим –","10":"и отдам их вместе с землями аммонитян восточным племенам, чтобы и памяти о народе аммонитян не осталось.","11":"И на Моав Я обрушу справедливую кару, и поймут они, что Я – Господь!","12":"Так говорит Господь Бог: Эдом жестоко мстит сынам Иудиным, месть его преступна!","13":"Вот за это, – так говорит Господь Бог, – Я обрушу руку Мою на Эдом, истреблю в Эдоме всех людей и животных, обращу его в руины. От Темана и до Дедана все падут от меча!","14":"Я отомщу эдомитянам руками народа Моего, Израиля, – он исполнит приговор, который Я вынес Эдому в ярости Моей и гневе. И познают они Мою месть! – говорит Господь Бог.","15":"Так говорит Господь Бог: жестока месть филистимлян, они глумятся, они полны смертельной злобы и извечной ненависти.","16":"Вот за это, – так говорит Господь Бог, – Я обрушу Мою руку на филистимлян, уничтожу керетян, истреблю остальных жителей морского побережья.","17":"Страшна будет Моя месть, Я обрушу на них Мою яростную кару! И когда отомщу им, они поймут, что Я – Господь!\"»"},"26":{"1":"В одиннадцатый год, в первый день первого месяца было мне слово Господа:","2":"«Человек! Тир хохочет, говоря об Иерусалиме: „Разрушены врата народов, все мне досталось! Я буду процветать, а он – лежать в руинах!\"","3":"Вот за это, – так говорит Господь Бог, – Я иду против тебя, Тир! Я подниму против тебя многочисленные народы, как море поднимает волны.","4":"Стены Тира они разрушат, разобьют его башни. И даже прах, что от тебя останется, Я вымету, сделаю тебя голой скалой.","5":"Станет он пустынным местом среди моря, где сушат рыбачьи сети. Так Я сказал, – говорит Господь Бог. – Станет Тир добычей народов.","6":"И дочери его, что живут на побережье, от меча погибнут, и все поймут, что Я – Господь Бог.","7":"Ибо так говорит Господь Бог: Я нашлю на Тир царя вавилонского Навуходоносора. С севера придет он, царь царей, с конями, колесницами и всадниками, с огромным войском.","8":"Дочерей твоих, что живут на побережье, он убьет мечом, а напротив тебя воздвигнет осадные башни, насыплет вал, выставит против тебя осадные щиты.","9":"Он обрушит на твои стены удары таранов, башни твои разобьет стенобитными орудиями.","10":"Тебя накроет туча пыли, поднятая его бесчисленной конницей. От криков всадников, от грохота колесничных колес будут сотрясаться твои стены. И он ворвется в твои ворота, словно через пролом в стене.","11":"Его кони будут топтать копытами твои улицы, жителей твоих он перебьет мечом, он повергнет на землю священные камни, на которые ты уповаешь.","12":"Враги разграбят твое богатство, возьмут в добычу твои товары. Стены твои они разрушат, красивые твои дома уничтожат. И камни, и бревна, и даже прах, что от тебя останется, они сбросят в море.","13":"Я положу конец твоим праздничным песням, цитры твои больше не будут звучать.","14":"Я превращу тебя в голую скалу! Ты станешь местом, где сушат рыбачьи сети, и никогда ты не будешь отстроен вновь, так сказал Я, Господь, – говорит Господь Бог.","15":"Так говорит Господь Бог Тиру: содрогнутся приморские страны от грохота, с которым ты падешь, от стонов умирающих, когда будет происходить в тебе страшная резня.","16":"Все вожди приморских стран сойдут со своих престолов, снимут мантии свои, сорвут с себя узорчатые облачения – одеянием их станет страх. Сядут они на землю, объятые трепетом, глядя с ужасом на то, что с тобой случилось.","17":"И оплачут тебя: О горе! Ты погиб, нет больше тебя, стоявший среди морей, прославленный город, могучая морская держава, перед жителями которой трепетали повсюду!","18":"Содрогнулись страны приморские, в день падения твоего пришли в ужас страны приморские от твоей гибели.","19":"Ибо так говорит Господь Бог: Я сделаю тебя городом разоренным, городом необитаемым. Я обрушу на тебя морскую пучину, и покроют тебя глубокие воды.","20":"Я низведу тебя к мертвецам в преисподней, к народу вечности. Я поселю тебя в подземном мире, в пустынях вечности, вместе с мертвецами в преисподней. Больше не быть тебе обитаемым, не красоваться на земле среди живых.","21":"Я обращу тебя в призрак, исчезнешь ты, и вовеки никто тебя не отыщет, – говорит Господь Бог»."},"27":{"1":"И было мне слово Господа:","2":"«Человек! Оплачь Тир!","3":"Скажи Тиру, восседающему у врат морских, торгующему с народами, с многочисленными приморскими странами: „Так говорит Господь: о Тир! Ты, называющий себя прекраснейшим кораблем!","4":"Владения твои – среди морей, строители твои сделали тебя прекрасным и совершенным.","5":"Борта твои они сделали из кипарисов с Сенира, ливанский кедр взяли для мачты.","6":"Из башанского дуба сделали тебе весла, остов твой – из бука с берегов киттейских.","7":"Из узорчатых льняных тканей египетских был сшит твой парус, по которому тебя узнавали. Навесы твои были из голубого и красного пурпура с берегов Элиши .","8":"Жители Сидона и Арвада служили у тебя гребцами. Умельцы твои, Тир, были у тебя корабельщиками.","9":"Старейшины Библа, его искусники работали на тебе, заделывали твои пробоины. Все корабли морские с их моряками тебе подчинялись, перевозили твои товары.","10":"Персы, лидййцы и ливийцы служили в твоем войске, были твоими солдатами. Щиты и шлемы они вешали на стены твои, что придавало тебе еще больший блеск.","11":"Сыны Арвада и Хелеха охраняли твои стены, жители Гаммада стояли на твоих башнях. Колчаны свои они развешивали на твоих стенах, что придавало тебе еще большую красоту.","12":"Торговал с тобою Таршиш, привлеченный твоим несметным богатством, – серебром, железом, оловом и свинцом он расплачивался с тобою.","13":"Яван, Тувал и Мешех торговали с тобою. Рабов и медную утварь они предлагали тебе на продажу.","14":"Купцы из Бет – Тогармы лошадьми, скакунами и мулами расплачивались с тобою.","15":"Торговали с тобой купцы из Дедана, многочисленные приморские страны были посредниками твоими. Слоновой костью и черным деревом они тебе платили.","16":"Торговали с тобой арамеи, привлеченные твоими бесчисленными товарами, – бирюзой, пурпурными и узорчатыми тканями, тончайшим льном, кораллами и рубинами они расплачивались с тобой.","17":"Иудея и страна Израилева торговали с тобою. Пшеницу из Миннита, сладости и финиковую патоку, оливковое масло и бальзам они предлагали тебе на продажу.","18":"Торговал с тобою Дамаск, привлеченный твоими бесчисленными товарами, несметным твоим богатством – вином из Хелбона и шерстью из Цахара,","19":"бочками с вином из Узала он расплачивался с тобой; изделия из железа, кассию и благовонный тростник предлагал тебе на продажу.","20":"Дедан торговал с тобою попонами дорогими.","21":"Купцы из Аравии и вожди Кедара были посредниками твоими. Ягнятами, баранами и козами торговали они с тобою.","22":"Купцы Савы и Раамы торговали с тобою. Лучшими благовониями, драгоценными камнями и золотом они расплачивались с тобою.","23":"Харран, Кане и Эден, купцы из Савы, Ассирия и Килмад торговали с тобой.","24":"Продавали они на твоих рынках роскошные одежды, голубые и узорчатые ткани, пестрые ковры, крепко скрученные канаты.","25":"Корабли таршишские перевозили твои товары. Разбогател ты и прославился среди морей.","26":"Твои гребцы вывели тебя в открытое море. Но восточный ветер разбил тебя в открытом море.","27":"Богатство твое, товары и грузы, матросы твои и корабельщики, мастера, что заделывали твои пробоины, торговцы твои и воины – все, кто был у тебя на борту, в пучине морской утонут в день твоего паденья!","28":"От крика твоих корабельщиков пастбища окрестные содрогнутся.","29":"Сойдут со своих кораблей гребцы, матросы и корабельщики и встанут на берегу.","30":"И громко заплачут о тебе, зарыдают горько. Головы они посыплют прахом, будут в пыли кататься.","31":"Головы обреют в знак траура, оденутся в дерюгу, будут горевать о тебе и плакать горьким плачем.","32":"Будут со стоном оплакивать тебя, и сложат плач: какой город сравнится с Тиром, погибшим в пучине моря?","33":"По морю ты вез свои товары, насыщал ими многие народы. Своим несметным богатством, своей торговлей обогащал ты царей земных!","34":"Но ты разбит морскою пучиной, все товары твои и люди ушли на дно!","35":"Все жители стран приморских судьбе твоей ужаснулись, цари их пришли в ужас, лица их исказились.","36":"Разноплеменные торговцы узнав о судьбе твоей, присвистнут. Ты обратился в призрак, исчез навеки!\"»"},"28":{"1":"И было мне слово Господа:","2":"«Человек! Скажи правителю Тира: „Так говорит Господь: вот, ты возгордился и говоришь:, Я – бог, я восседаю на божественном престоле среди моря!' Но ты – человек, а не Бог, хоть и считаешь себя равным Богу.","3":"Ты превзошел мудростью своей Даниила, ни одна тайна от тебя не скрыта,","4":"мудростью своей и умом ты достиг могущества, наполнил свои сокровищницы золотом и серебром.","5":"Умелой торговлей ты умножил свое богатство и возгордился этим богатством.","6":"Но так говорит Господь Бог: ты возомнил, что равен Богу, –","7":"за это Я пошлю против тебя чужеземцев, самые жестокие народы. Они обнажат свои мечи против блистательной твоей мудрости и величие твое растопчут.","8":"Они низвергнут тебя в преисподнюю, ты погибнешь лютой смертью среди морей.","9":"Что, и перед лицом убийц все будешь твердить:, Я – бог? В их руках ты не бог, ты – человек.","10":"Ты умрешь смертью необрезанных, от руки чужеземцев. Так говорю Я, Господь Бог\"».","11":"И было мне слово Господа:","12":"«Человек! Оплачь царя Тира и скажи ему: „Так говорит Господь Бог: ты был отмечен печатью совершенства, исполнен мудрости и совершенной красоты.","13":"Ты жил в Эдеме, в саду Божьем. Твои одеяния были сплошь драгоценные камни: рубины, хризолиты, гагаты, топазы, шохам, яшма, лазурит, бирюза, изумруды. Украшения твои и облаченья твои были сделаны из золота. Они были на тебе с самого дня сотворения твоего.","14":"Тебя, сверкающего херувима с осеняющими крылами, Я поселил на святой горе Божьей. Там ты жил – и ходил среди огненных камней.","15":"Безупречны были твои поступки с самого дня сотворения твоего, но прошло время – и обнаружилось в тебе зло.","16":"Ты вел обширную торговлю – и стал полон злодеяниями и грехами. И Я низверг тебя с горы Божьей, о херувим с осеняющими крылами, положил конец твоему пребыванию среди огненных камней.","17":"Ты возгордился из-за своей красоты и растерял свою мудрость из-за блеска своего. Я низверг тебя на землю, обрек тебя на позор перед царями.","18":"Множеством своих преступлений, неправедной торговлей своей ты осквернил свои святилища. Я зажег в тебе пламя – оно тебя уничтожило! У всех на виду Я превратил тебя в пепел, лежащий на земле!","19":"Все народы, что знали тебя, пришли в ужас, видя твою участь. Ты обратился в призрак, исчез навеки!\"»","20":"И было мне слово Господа:","21":"«Человек! Обрати свой взор против Си – дона и произнеси против него пророчество!","22":"Скажи: „Так говорит Господь Бог: Я иду против тебя, Сидон! И через то, что Я сотворю с тобою, Я явлю Мою славу! И поймут все, что Я – Господь, когда Я устрою суд над Сидоном! Так Я явлю Мою святость!","23":"Я нашлю на него мор, кровь зальет его улицы! Трупами он будет завален, когда меч обрушится на него со всех сторон! И поймут тогда все, что Я – Господь!","24":"Народ Израилев не будет больше страдать от острых шипов, от колючих тернов, от всех соседей своих, которые глумились над ним. И поймут, что Я – Господь Бог!","25":"Так говорит Господь Бог: Я соберу народ Израилев из стран, по которым он был рассеян, и явлю Мою святость – через то, что Я совершу с ним на глазах у народов. Вновь поселится он на своей земле – на земле, которую Я даровал рабу Моему Иакову.","26":"И будет жить на ней в безопасности, будет строить дома и разводить виноградники. Он будет жить в безопасности, а Я устрою суд над всеми его соседями, что ныне над ним глумятся, – и тогда поймут сыны Израилевы, что Я – Господь Бог их!\"»"},"29":{"1":"В десятый год, в двенадцатый день десятого месяца было мне слово Господа:","2":"«Человек! Обрати свой взор против фараона, царя Египетского, и произнеси пророчество против него и против всего Египта.","3":"Возвести, скажи: „Так говорит Господь Бог: Я иду против тебя, фараон, царь Египетский, огромный крокодил! Ты лежишь среди рукавов Нила и говоришь:, Нил принадлежит мне! Я создал его для Себя!'","4":"Но Я вставлю крюк тебе в челюсть, а рыб, живущих в твоей реке, заставлю облепить твою чешую. И вытащу тебя из твоей реки вместе со всеми рыбами твоей реки, что облепили твою чешую.","5":"Я брошу тебя в пустыне – и тебя, и всех рыб твоей реки. На открытом поле вы будете лежать, никто не подберет вас, не похоронит. Диким зверям и птицам небесным Я отдам вас на съедение.","6":"И поймут все жители Египта, что Я – Господь Бог! Ты был для народа Израилева костылем ломким:","7":"когда ухватился за тебя народ Израилев, ты надломился, вонзился ему в плечо. Когда оперся на тебя народ Израилев, ты сломался, и ноги его подкосились.","8":"Потому так говорит Господь Бог: Я пошлю против тебя меч и уничтожу в тебе и людей, и животных!","9":"И станет страна Египта развалинами и пустыней, и поймут они, что Я – Господь!","10":"Говорил Египет:, Нил принадлежит мне, я его создал, – вот за это Я иду против тебя и против твоей реки с ее рукавами. Я сделаю землю Египта пустыней из пустынь, развалинами – от Мигдола и до Сиены, до самой границы с Кушем.","11":"Не ступит больше на нее нога человека, не будут жить на ней звери, на сорок лет она останется необитаемой.","12":"Я сделаю Египет самым опустошенным из всех стран опустошенных, и все города его сорок лет будут самыми разоренными из всех городов разоренных. Я рассею египтян среди народов, развею по странам.","13":"Так говорит Господь Бог: когда пройдут сорок лет, Я соберу египтян из всех стран, по которым они были разбросаны.","14":"Я верну египтян из плена, поселю их в стране Патрос, откуда они родом, и будет у них там свое слабое царство.","15":"Из всех царств будет оно самым слабым, не вознесется больше над народами. Я сделаю его ничтожным, и не сможет оно владычествовать над народами.","16":"И не станет больше народ Израилев на него полагаться: Египет будет лишь напоминанием о том, как обманулись сыны Израилевы, понадеявшись на него. И поймут они, что Я – Господь Бог!\"»","17":"В двадцать седьмой год, в первый день первого месяца было мне слово Господа:","18":"«Человек! Навуходоносор, царь Вавилона, измучил свое войско изнурительной осадой Тира. Волосы на головах его воинов вылезли, плечи стерты, но нет никакой награды ни ему, ни войску его за осаду Тира, за все труды, которые пришлось вынести.","19":"Потому так говорит Господь Бог: Я отдаю Египет Навуходоносору, царю Вавилона. Он отнимет богатства Египта, разграбит его и оберет, и это будет наградой его войску.","20":"В награду за все те труды, которые пришлось вытерпеть Навуходоносору, Я отдаю ему Египет, ибо ради Меня трудилось его войско, – говорит Господь Бог.","21":"В тот день Я вновь сделаю народ Израилев сильным, и ты сможешь открыто говорить перед ними. И поймут они, что Я – Господь Бог!»"},"30":{"1":"И было мне слово Господа:","2":"«Человек! Произнеси пророчество, скажи: „Так говорит Господь Бог: рыдайте, говорите: о, день горестный!","3":"Ибо близок день, близок день Господень! День бури! Придет час всех народов!","4":"Меч обрушится на Египет, и мука охватит Куш, когда погибнет Египет. Враги разграбят богатство Египта, и до основания он будет разрушен!","5":"Кушиты, ливийцы, лидийцы и прочий разноплеменный люд, кувийцы и сыны страны договора – все погибнут от меча вместе с египтянами.","6":"Так говорит Господь: падут подпоры Египта, гордая его сила исчезнет. От Мигдола и до Сиены все погибнут от меча, – говорит Господь Бог. –","7":"И будет Египет самой опустошенной страной из всех стран опустошенных, его города – самыми разоренными из всех городов разоренных.","8":"И поймут они, что Я – Господь, когда Я предам Египет огню, и все подпоры его падут.","9":"В тот день Я пошлю на кораблях вестников, и они повергнут в ужас кушитов, которые думают, что живут в безопасности, – охватит кушитов ужас в день гибели Египта. Скоро это сбудется!","10":"Так говорит Господь Бог: Я уничтожу многолюдный Египет рукою Навуходоносора, царя вавилонского.","11":"Вместе со своим народом, жесточайшим из всех народов, будет он Мной приведен, чтобы уничтожить Египет. Мечи свои они занесут над Египтом и наполнят страну убитыми.","12":"И Я превращу все рукава Нила в пересохшие русла, Я отдам эту страну в руки жестоких злодеев. Рукой чужеземцев Я опустошу эту землю и все, что на ней есть. Так говорю Я, Господь Бог.","13":"Так говорит Господь Бог: Я истреблю идолов в Нофе, уничтожу изваяния богов. И не станет властителя в стране Египетской, Я повергну в ужас Египет.","14":"Я опустошу Патрос, предам огню Цоан, Я устрою суд над Но!","15":"Я изолью Мою ярость на Син, твердыню Египта, Я уничтожу многолюдный Но!","16":"Я предам Египет огню, Син будет корчиться в муках, Но будет взят, на Ноф нападут враги среди бела дня.","17":"Юноши Авена и Пи – Бесета падут от меча, а женщины будут уведены в плен.","18":"Померкнет день в Тахпанхесе, когда Я сокрушу там жезлы Египта. Исчезнет гордая его сила, туча накроет город, дочери его будут в плен уведены.","19":"Я совершу суд над Египтом, и поймут они, что Я – Господь!\"»","20":"В одиннадцатый год, в седьмой день первого месяца было мне слово Господа:","21":"«Человек! Я сломал руку фараону, царю египетскому. И вот, никто не накладывает на нее повязки, не лечит ее, не перевязывает – чтобы выздоровела она и снова могла держать меч.","22":"Так говорит Господь Бог: Я иду против тебя, фараон, царь египетский! И теперь Я переломаю тебе обе руки – и здоровую, и уже сломанную! Я заставлю меч выпасть из твоих рук!","23":"Я рассею египтян среди народов, развею по странам!","24":"И сделаю сильной руку царя вавилонского и вложу в нее Мой меч, а руки фараона переломаю! Смертельно раненный, будет фараон стонать перед вавилонским царем.","25":"Я сделаю сильной руку царя вавилонского, а руки фараона обессилеют! И поймут все, что Я – Господь Бог, когда Я вручу Мой меч царю Вавилона, Навуходоносору, и тот занесет меч над Египтом!","26":"Я рассею египтян по разным народам, развею по странам, и поймут тогда, что Я – Господь!»"},"31":{"1":"В одиннадцатый год, в первый день третьего месяца было мне слово Господа:","2":"«Человек! Скажи фараону, царю Египта, и его полчищам: „С кем ты сравнишься величием своим?","3":"С Ассирией? С этим кедром ливанским? Прекрасными были ветви его, листва давала густую тень. Был высок его ствол, вершиной касался облаков.","4":"Воды питали его, пучина взрастила. Реками своими она омывала место, где он рос, остальным же деревьям лишь ручейки давала.","5":"Потому он стал выше всех остальных деревьев. Ветви его росли, крона его разрасталась, ибо щедро он был напоен водою.","6":"В листве его вили гнезда птицы, под ветвями – звери детенышей выводили, в тени его жили многочисленные народы.","7":"Прекрасен он был и высок, с распростертыми ветвями, ибо корни его щедро питались водою.","8":"Даже кедры в Божьем саду были ниже его, у кипарисов не было столь густых ветвей, у платанов не было такой кроны. Ни одно из деревьев в Божьем саду не могло по красоте с ним сравниться.","9":"Я сделал его прекрасным и ветвистым, все деревья Эдема, что росли в Божьем саду, завидовали ему.","10":"Так говорит Господь Бог: вырос он высоким, вершиной своей облаков касался, и возгордился своим величием.","11":"Вот за это Я отдал его в руки властителя народов, чтобы тот поступил с ним по заслугам, – Я отверг его.","12":"Срубили его чужеземцы, самые жестокие из народов, бросили его на горах. Ветви его разбросаны по всем долинам, обломанные сучья – по всем лощинам. Ушли из-под его тени народы земные, оставили его.","13":"На поваленном стволе свили гнезда птицы, дикие звери среди ветвей его.","14":"Так пусть не возносится ни одно дерево, растущее на орошенной земле, пусть не касается вершиной облаков! Пусть могучие стволы деревьев, напоенных водою, не поднимаются высоко! Будут все они обречены на смерть, все окажутся в подземном мире, среди мертвецов в преисподней!","15":"Так говорит Господь Бог: день, когда сошел он в Шеол, Я сделал днем плача: для этого Я замкнул пучину и запер ее реки – и великие воды остановились. Для этого Я погрузил весь Ливан во мрак – и все деревья лесные зачахли.","16":"Я заставил народы содрогнуться от грохота, когда пал он. Я низвел его в Шеол, к мертвецам в преисподнюю. И тогда обрадовались в подземном мире все дерева Эдема, лучшие, отборные дерева Ливана, некогда напоенные водою.","17":"И союзники его, жившие под тенью его среди народов, вместе с ним сошли они в Шеол, к погибшим от меча.","18":"С каким из деревьев эдемских сравнишься ты славой и силой? Как и они, ты сойдешь в подземный мир! Будешь лежать среди необрезанных, погибших от меча. Вот участь, которая ждет фараона и все полчища его, – говорит Господь Бог\"»."},"32":{"1":"В двенадцатый год, в первый день двенадцатого месяца было мне слово Господа:","2":"«Человек! Оплачь фараона, царя Египта, скажи ему: „Ты считал себя львом среди народов, ты, подобный чудищу морскому! Вспенивал Ты реки свои, ногами бил по воде, мутил потоки.","3":"Так говорит Господь Бог: Я накрою тебя Моей сетью: соберутся многочисленные народы и вытащат тебя Моим неводом.","4":"Я вышвырну тебя на землю, на открытом поле брошу, чтобы птицы небесные на тебя садились, чтобы дикие звери тебя пожирали.","5":"Твою плоть Я по горам разбросаю, останками твоими наполню долины!","6":"Я напою землю потоками твоей крови, и горы, и лощины наполнятся ею.","7":"Ты угаснешь – и Я скрою небо, звезды спрячу во мраке, солнце покрою мглою, и луна светить перестанет.","8":"Все светила небесные Я покрою мраком над тобою, землю твою погружу во тьму, – говорит Господь Бог.","9":"Я наполню страхом сердца многочисленных народов, когда приведу остатки твоих жителей в страны, о которых они и не знали.","10":"Я поражу ужасом многочисленные народы, которые увидят твою участь. Цари их содрогнутся, глядя на тебя, а Я буду потрясать Моим мечом перед их лицами. Когда ты падешь, каждый из них станет ежечасно трепетать за свою жизнь.","11":"Так говорит Господь Бог: меч царя вавилонского обрушится на тебя.","12":"Я истреблю твои полчища мечами сильных воинов, что принадлежат к самому жестокому народу из всех народов. Они положат конец гордыне Египта, и все полчища его погибнут!","13":"Я уничтожу все стада, что пасутся возле этой великой реки, и ни нога человека, ни копыто животного больше не будет мутить в ней воду.","14":"Я сделаю воды этой реки незамутненными, будут тихо они струиться, словно масло, – говорит Господь Бог. –","15":"Когда Я превращу землю Египта в пустыню и все, что на ней есть, погибнет, когда Я уничтожу всех живущих на ней, тогда поймут, что Я – Господь!","16":"Вот плач, которым дочери народов будут оплакивать Египет и весь его многочисленный народ, – говорит Господь Бог\"».","17":"В двенадцатый год, в пятнадцатый день первого месяца было мне слово Господа:","18":"«Человек! Оплачь многочисленный народ Египта, низринь их – и египтян, и дочерей народов знаменитых – в подземный мир, к мертвецам в преисподнюю.","19":"Чем ты краше других? Сойди, ложись среди необрезанных!","20":"Среди сраженных мечом будут лежать египтяне! Меч уже приготовлен – волочите туда Египет и все его полчища!","21":"Могучие воины, сошедшие в Шеол, скажут о Египте и его союзниках: „Вот и они тоже пали, лежат среди необрезанных, убитые мечом!\"","22":"Там Ассирия и все ее воины, кругом – одни могилы, все мертвецы, павшие от меча.","23":"Могилы их – в самой глубине преисподней. Все войско ее – одни могилы, все мертвецы, павшие от меча. А когда-то они внушали ужас на земле живых!","24":"Там Элам и все его полчища, кругом – одни могилы, все мертвецы, павшие от меча, необрезанные, сошедшие в подземный мир. А когда-то они внушали ужас на земле живых. Теперь покрыты позором среди мертвецов в преисподней.","25":"Среди убитых теперь ложе Элама, вместе с его полчищами. Кругом – одни могилы, все необрезанные, убитые мечом. А когда-то они внушали ужас на земле живых. Теперь покрыты позором среди мертвецов в преисподней, среди убитых лежат.","26":"Там Мешех и Тувал и все их полчища, кругом – одни могилы, все необрезанные, убитые мечом. А когда-то они внушали ужас на земле живых.","27":"Суждено и египтянам лечь вместе с павшими воинами необрезанными, сошедшими в Шеол в воинских доспехах, под головами которых меч, на костях – щит. А когда-то внушали они ужас на земле живых.","28":"Будешь и ты уничтожен, словно необрезанные, ляжешь среди убитых мечом!","29":"Там Эдом, цари его и вожди. Со всем своим могуществом лежат они – среди убитых мечом, среди необрезанных, среди мертвецов в преисподней.","30":"Там северные владыки, там сидоняне, сошли они к убитым. Могучи они были и ужасны, теперь покрыты позором, лежат они среди необрезанных, среди убитых мечом, покрыты они позором, лежат среди мертвецов в преисподней.","31":"Увидит их фараон, и уже не так горько ему будет, что все его войско и сам он, и все его полчища пали от меча, – говорит Господь Бог.","32":"Я заставлю землю живых трепетать предо Мною! А фараон и все его полчища будут лежать среди необрезанных, среди убитых мечом! – говорит Господь Бог»."},"33":{"1":"И было мне слово Господа:","2":"«Человек! Обратись к сыновьям своего народа и скажи им: если Я насылаю на страну меч, а ее жители избрали дозорного,","3":"и если этот дозорный, увидев меч, надвигающийся на страну, затрубил в трубу, предупреждая народ, –","4":"то всякий, кто услышит звук трубы, но не остережется, будет сам повинен в своей смерти, когда меч придет и убьет его.","5":"Он слышал звук трубы, но не остерегся, – и потому сам повинен в своей смерти. А кто остережется, тот спасет свою жизнь.","6":"Если же дозорный, видя надвигающийся меч, не затрубил в трубу и народ не был предупрежден, и меч пришел и убил людей, то убитые пали за свои грехи, но вину за их смерть Я возложу на дозорного.","7":"Тебя, человек, Я поставил дозорным для народа Израилева! Ты будешь слушать слово из Моих уст и будешь от Моего лица предостерегать народ Израилев!","8":"Если Я вынес злодею приговор: „Злодей! Ты умрешь!\", а ты, человек, не предупредишь его, не предостережешь от преступного пути, то он умрет за свои преступления, а тебя Я призову к ответу за его смерть!","9":"Если же ты предостережешь злодея, скажешь ему, чтобы он оставил свой путь, а он этого не сделает, то он умрет за свои преступления, но ты – избежишь кары.","10":"Человек! Скажи народу Израилеву: „Вы твердите:, Мы несем бремя наших грехов и преступлений! Они губят нас. Разве можем мы остаться в живых?'\"","11":"Скажи им: „Клянусь Собою, – говорит Господь Бог, – Я не хочу смерти грешника, Я хочу, чтобы он оставил свой путь и был жив! Оставьте, оставьте ваши злые пути! Зачем тебе гибнуть, народ Израилев!\"","12":"Человек! Скажи сыновьям своего народа: „Праведность праведника не спасет его, когда он согрешит. Злодей не погибнет за свое прошлое злодейство, если отступит от него, равно как и праведник не останется в живых, если станет грешить.","13":"Если Я сказал о праведнике:, Он будет жив!' и он уверовал в свою праведность и стал творить зло, то вся его праведность ему не зачтется! За содеянное им зло – он умрет!","14":"Если Я вынес злодею приговор:, Ты умрешь!', а он оставил свои преступления, стал поступать справедливо и праведно,","15":"вернул залог, украденное возместил, стал жить по законам, дающим жизнь, и больше не совершает зла, – то не умрет он, но будет жить!","16":"Все его прошлые грехи не припомнятся ему, ведь он стал поступать справедливо и праведно – и будет жить!\"","17":"Говорят люди твоего народа: „Несправедлив суд Господа!\" Нет, это их суд несправедлив!","18":"Если отступит праведник от праведности своей, будет совершать зло, – он за это умрет.","19":"Если злодей отступит от зла, будет поступать справедливо и праведно, – он будет жить за это.","20":"А вы говорите: „Несправедлив суд Господа!\" Нет, о народ Израилев, каждого из вас Я сужу по делам его».","21":"На двенадцатый год после того, как мы были переселены, в пятый день десятого месяца, пришел ко мне один человек, спасшийся из Иерусалима, и сказал: «Город пал!»","22":"Но накануне вечером, еще до прихода этого беженца, уже была на мне рука Господня. Еще до того, как утром пришел ко мне этот человек, Господь отверз мои уста. Уста мои разомкнулись, и я перестал безмолвствовать.","23":"И было мне слово Господа:","24":"«Человек! Те, кто остались жить среди руин на земле Израилевой, говорят: „Авраам был один, а получил во владение эту землю. Нас больше – и нам отдана эта земля во владение!\"","25":"Но скажи им: „Так говорит Господь Бог: вы едите с кровью, обращаете взоры к идолам, проливаете кровь! И вам владеть этой землей?","26":"Вы живете насилием, совершаете мерзости, один оскверняет жену другого! И вам владеть этой землей?\"","27":"Так скажи им: „Так говорит Господь Бог: клянусь Собою! Те, кто живут среди руин, от меча падут. Тех, кто в поле, Я отдам диким зверям на съедение. А те, кто прячутся в крепостях и пещерах, умрут от мора.","28":"Я сделаю эту страну пустыней из пустынь, истощится гордая сила ее. Опустеют горы Израилевы, никто больше не будет по ним ходить!","29":"Поймут эти люди, что Я – Господь, когда Я сделаю их землю пустыней из пустынь за все мерзости, которые они совершали\".","30":"О тебе, человек, твой народ судачит – стоят эти люди возле стен и дверей своих домов и говорят друг другу, брат брату: „Пойдем, послушаем, какое еще там слово пришло от Господа!\"","31":"И приходят к тебе толпами. Садится пред тобою Мой народ и слушает твои слова, но не исполняет их. В их устах твои слова становятся красивыми побасенками, ибо делают они только то, что им выгодно.","32":"Твои речи для них – что красивая песенка, хорошо спетая под искусную музыку. Слушают они твои слова и не исполняют их.","33":"Но когда все это сбудется – уже сбывается! – вот тогда поймут они, что был среди них пророк»."},"34":{"1":"Было мне слово Господа:","2":"«Человек! Произнеси пророчество против пастухов Израилевых, произнеси пророчество и скажи им, пастухам: „Так говорит Господь Бог: горе пастухам Израилевым, которые пасут самих себя! Разве не стадо должны пасти пастухи?","3":"Вы питаетесь молоком, вы одеваетесь в одежду из шерсти, вы закалываете откормленных овец, но о стаде вы не заботитесь.","4":"Ослабевших вы не поддерживаете, больных не лечите, раненых не перевязываете, отбившихся не возвращаете, пропавших не ищете. Вы обращаетесь со своим стадом жестоко и сурово.","5":"И разбрелись овцы, которых никто не пасет, – разбрелись и стали пищей для диких зверей.","6":"Блуждает Мое стадо по всем горам, по всем холмам высоким, по всей земле Мое стадо рассеялось, и никто их не ищет, никто не разыскивает.","7":"Потому, пастухи, слушайте слово Господа:","8":"Клянусь Собою! – говорит Господь Бог. – За то, что овцы Мои, которых никто не пасет, стали добычей и пищей диким зверям, за то, что пастухи Мои не заботятся о Моих овцах, пасут себя самих, а не стадо, –","9":"слушайте, пастухи, слово Господа.","10":"Так говорит Господь Бог: Я иду против пастухов! Я призову их к ответу за Мое стадо. Я больше не дам им пасти Моих овец – и не будут больше пастухи пасти самих себя! Я избавлю Мое стадо от их зубов, впредь не будет оно их пищей!","11":"Так говорит Господь Бог: Я сам отыщу Моих овец, всех их пересчитаю!","12":"Как пастух пересчитывает сво – их овец, когда они разбредутся, так и Я пересчитаю Мое стадо. Я вызволю их отовсюду, куда их забросило в день бури и тьмы.","13":"Я уведу их из владений чужих народов, соберу их из разных земель и приведу назад в их страну. Я буду пасти их на горах Израилевых, возле ручьев, у всех селений этой страны.","14":"На прекрасных лугах Я буду пасти их, на высоких горах Израилевых будет их пастбище. Там будут отдыхать они, на прекрасном пастбище, будут пастись на сочных лугах, на горах Израилевых.","15":"Я сам буду пасти Мое стадо, Я Сам дарую ему отдых, – говорит Господь Бог. –","16":"Отбившуюся овцу Я отыщу, заблудшую – возвращу, раненую – перевяжу, ослабевшую – поддержу, а разжиревшую и заматеревшую – уничтожу. Я буду пасти их как подобает!","17":"Вы – стадо Мое! – так говорит Господь Бог. – Я Сам буду разбирать тяжбы между овцами стада Моего, между баранами и козлами!","18":"Разве мало вам того, что вы пасетесь на прекрасном пастбище? Зачем оставшуюся траву вы топчете копытами? Разве мало вам того, что вы пьете чистую воду? Зачем оставшуюся воду вы взбаламутили своими копытами?","19":"И вот, другие мои овцы едят то, что вы потоптали копытами, и пьют воду, взбаламученную вашими копытами!","20":"Так говорит им Господь Бог: Я Сам буду разбирать тяжбы между тучными овцами и тощими.","21":"Вы толкаетесь боками и плечами, вы бодаете рогами слабых, пока не разгоните их!","22":"Но Я спасу Моих овец, не будут они больше ничьей добычей, Я Сам буду разбирать тяжбы между овцами.","23":"Одного пастуха Я поставлю над ними, чтоб он пас их, – раба Моего Давида. Он будет пасти их, он будет для них пастухом!","24":"Я, Господь, буду их Богом, а раб Мой Давид будет их вождем. Так говорю Я, Господь.","25":"Я заключу с ними договор, который принесет им благоденствие. Я истреблю в этой стране все хищное зверье – чтоб могли они жить безмятежно в степи и спать спокойно в лесу.","26":"Я дарую благословение им и всей стране вокруг Моей горы. Я буду в срок посылать им дожди, и будут эти дожди благословенными.","27":"Деревья будут приносить свои плоды, и земля – давать урожай. Будут жить они на своей земле в безопасности. И поймут они, что Я – Господь, когда Я разломаю ярмо их и освобожу от поработителей.","28":"И не будут они больше добычей других народов, и звери не будут больше пожирать их. Будут жить они в безопасности, и никто больше не будет наводить на них страх.","29":"Я стану посылать им урожаи на славу, и никто в их стране не будет больше гибнуть от голода, и не придется им больше терпеть поношения от других народов.","30":"И поймут они, что Я, Господь, Бог их, – с ними! Что они, сыны Израилевы, – народ Мой! – говорит Господь Бог. –","31":"Вы – овцы Мои, овцы на пастбище Моем. Вы – люди, а Я – Бог ваш, – говорит Господь Бог\"»."},"35":{"1":"И было мне слово Господа:","2":"«Человек! Обрати свой взор против горной страны Сеир и произнеси пророчество о ней.","3":"Скажи ей: „Так говорит Господь Бог: Я иду против тебя, горная страна Сеир! Я занес над тобою Мою руку, Я сделаю тебя пустыней необитаемой!","4":"Я превращу твои города в руины, и ты станешь пустыней, и поймешь, что Я – Господь!","5":"За твою вековечную ненависть, за то, что ты подняла меч на сынов Израилевых, когда пришла к ним беда, время расплаты,","6":"за это, клянусь Собою, – говорит Господь Бог, – Я залью тебя кровью, кровопролитие будет преследовать тебя по пятам! Не гнушалась ты кровопролитием, вот и будет оно преследовать тебя по пятам!","7":"Я превращу горы Сеира в пустыню из пустынь, и никто не будет по ним ходить.","8":"Я наполню трупами горы Сеира! На холмах, в долинах и в лощинах будут лежать убитые мечом!","9":"Вечной пустыней Я сделаю тебя, и города твои никогда не будут заселены вновь. И поймете вы, что Я – Господь!","10":"Ты говорила:, Эти две страны, земли этих двух народов станут нашими, мы завладеем ими , – хотя там был Господь!","11":"Но клянусь Собою, – говорит Господь Бог, – Я отплачу тебе за ярость твою, за зависть, которую ты питала к сынам Израилевым, за ненависть твою к ним! Я явлю Себя сынам Израилевым – как твой Судия!","12":"И поймешь ты, что Я – Господь. Слышал Я, как ты глумилась над горами Израилевыми:, Опустошены они! Стали нашей добычей!'","13":"Ты в своих речах превозносилась передо Мною, говорила наглые слова против Меня! Слышал Я это!","14":"Так говорит Господь Бог: в то самое время, когда вся земля будет ликовать, Я тебя превращу в пустыню!","15":"Ты радовалась, что владения народа Израилева стали пустыней – вот и тебя Я подвергну той же участи! Ты сама станешь пустыней, горная страна Сеир, – вся страна Эдомская! И поймут, что Я – Господь!\"»"},"36":{"1":"«Человек! Произнеси пророчество горам Израилевым. Скажи: „Горы Израилевы! Слушайте слово Господа!","2":"Так говорит Господь Бог: ваши враги хохочут, кричат:, Вечные вершины теперь наши!'\"","3":"И потому произнеси пророчество, скажи: „Так говорит Господь Бог: потому, именно потому, что опустошали вас и терзали со всех сторон, что прочие народы властвовали над вами, что злословили они вас и поносили, –","4":"слушайте, горы Израилевы, слово Господа Бога! Так говорит Господь Бог горам, холмам, лощинам, долинам, руинам безлюдным, брошенным городам, которые стали добычей окрестных народов и посмешищем для них,","5":"так говорит Господь Бог: пылая яростью, Я изрекаю Мой приговор всем прочим народам и всему Эдому. Моей землей они завладели, ликуя и глумясь, грабят пастбища ее\".","6":"Потому произнеси пророчество о земле Израилевой, скажи горам, холмам, ущельям и долинам: „Так говорит Господь Бог: в ярости Моей, в гневе Моем изрекаю Я Мое слово, ибо вы терпите унижения от других народов!","7":"Так говорит Господь Бог: Я клянусь, эти окрестные народы сами будут унижены!","8":"А вы, горы Израилевы, вы покроетесь деревьями ветвистыми и будете приносить плоды для народа Моего Израиля – он скоро уже вернется сюда!","9":"Я обращу Мой взор на вас – и вновь вас будут возделывать, будут засевать!","10":"Я поселю на вас множество людей – весь народ Израилев! Будут вновь заселены города и отстроены руины.","11":"Я заселю вас множеством людей и животных, будут они размножаться и плодиться. Я сделаю вас такими же населенными, как прежде. Я буду делать вам еще больше добра, чем прежде, и поймете вы, что Я – Господь!","12":"Я сделаю так, что вновь будут ходить по вам люди – народ Мой Израиль. Будет он владеть вами, вы будете его достоянием, и никогда больше вы не будете нести смерть сынам народа Моего.","13":"Так говорит Господь Бог этой земле: говорят о тебе:, Ты – земля, которая пожирает людей и несет смерть своим жителям!'","14":"Но больше ты не будешь пожирать людей, не будешь больше нести смерть своим жителям, – говорит Господь Бог. –","15":"Я сделаю так, что впредь уже не придется тебе слышать поношения от народов, терпеть унижения от них, и своим жителям ты не будешь больше нести смерть! – говорит Господь Бог\"».","16":"И было мне слово Господа:","17":"«Человек! Когда народ Израилев жил на своей земле, он осквернял ее поступками своими и делами. Их жизнь была передо Мной нечиста – как женщина во время месячных.","18":"И Я излил на этих людей Мою ярость – за кровь, которую проливали они на эту землю, за идолов, которыми оскверняли ее!","19":"Я рассеял их среди других народов – и вот теперь они разбросаны по странам. Я справедливо их покарал за поступки их и дела.","20":"Но к какому бы народу ни пришел народ Израилев, он самим своим приходом бесславил Мое святое имя, ибо там говорили: „И это народ Господа?! Изгнанный из Его страны…\"","21":"И стало жаль Мне, что имя Мое святое обесславлено тем, что народ Израилев блуждает среди чужих народов.","22":"Потому скажи народу Израилеву: „Так говорит Господь Бог: Я делаю это не ради тебя, народ Израилев, а ради имени Моего святого, которое обесславлено тем, что ты блуждаешь среди чужих народов.","23":"Я явлю святость Моего великого имени, которое ныне, из-за вас, обесславлено среди народов. Поймут все народы, что Я – Господь, – говорит Господь Бог, – когда Я явлю им святость Мою – через то, что Я совершу с вами у них на глазах.","24":"Я заберу вас от этих народов, соберу вас из всех стран – и приведу вас на вашу землю.","25":"Я окроплю вас водой очищения, чтобы вы очистились от своей скверны. От всех идолов ваших Я очищу вас.","26":"И Я дам вам новое сердце, новый дух вложу в вас. Я вырву из вашей груди сердце каменное и вложу сердце из живой плоти.","27":"Мой дух Я вложу в вас и сделаю так, чтобы вы жили по Моим законам, строго соблюдали Мои предписания и исполняли их.","28":"И будете вы тогда жить на земле, которую Я дал вашим отцам, и будете Моим народом, а Я буду вашим Богом.","29":"Я избавлю вас от вашей скверны и призову обильный урожай, – и впредь не допущу, чтобы вы страдали от голода.","30":"Я в изобилии дам вам плоды деревьев и урожай полей, чтобы больше вам не приходилось из-за голода терпеть унижения от соседних народов.","31":"И тогда, вспоминая о своих злых делах, о недобрых деяниях своих, вы станете испытывать отвращение к самим себе за ваши преступления и мерзости.","32":"Нет, не ради вас Я все это сделаю, знайте это, – говорит Господь Бог. – Стыдись своих дел, народ Израилев, сгорай от стыда!","33":"Так говорит Господь Бог: придет день, когда Я очищу вас от всех ваших мерзостей, когда Я заселю города, когда руины будут отстроены,","34":"а разоренная земля, которая ныне всем кажется пустыней, будет вновь возделываться.","35":"И тогда будут вос – клицать:, Земля, что была разорена, стала словно сад Эдемский! Города, что лежали в руинах, опустошенные и разрушенные, вновь отстроены, укреплены, населены*.","36":"И поймут окрестные народы, что Я, Господь, отстраиваю разрушенное, возделываю опустошенное. Так Я, Господь, сказал, и так Я сделал!","37":"Так говорит Господь Бог: Я исполню то, о чем просит Меня народ Израилев: сделаю их многочисленными, словно стадо людское.","38":"Как Иерусалим во время празднеств наполнялся жертвенными овцами, так разрушенные ныне города наполнятся стадами людскими. И поймут все, что Я – Господь!\"»"},"37":{"1":"Простер Господь надо мной Свою руку – и унес меня Духом Своим и опустил посреди долины. И была та долина полна костей.","2":"Он стал водить меня вокруг костей – их было несметное множество в той долине, и были они совершенно сухими.","3":"Он сказал мне: «Человек! Могут ли эти кости ожить?» Я ответил: «Господь Бог! Это знаешь Ты один!»","4":"Он сказал мне: «Произнеси пророчество этим костям, скажи им: „Кости сухие! Слушайте слово Господа!","5":"Так говорит Господь этим костям: Я вложу в вас дух, и вы оживете.","6":"Я прикреплю к вам сухожилия, наращу мясо и покрою вас кожей. Я дам вам дух, и вы оживете. И тогда поймете вы, что Я – Господь\"».","7":"И я произнес пророчество, как было мне велено. Когда я произносил это пророчество, раздался шум и земля задрожала – кости стали соединяться друг с другом.","8":"И увидел я, что появились на них сухожилия, наросло мясо, а сверху покрыла их кожа. Но дыхания жизни в них еще не было.","9":"Тогда Он сказал мне: «Произнеси пророчество духу, произнеси пророчество, человек, скажи духу: „Так говорит Господь Бог: от четырех ветров приди, дух, и вдохни жизнь в убитых – и они оживут!\"»","10":"И я произнес пророчество, как Он велел мне, и вошел в них дух, и они ожили. Встали они, и было их несметное полчище.","11":"Тогда Он сказал мне: «Человек! Эти кости – народ Израилев, который говорит: Кости наши иссохли, погибла надежда, мы обречены!","12":"Но произнеси пророчество, скажи им: „Так говорит Господь Бог: Я открою ваши могилы и выведу вас из могил, о народ Мой, и приведу вас на землю Израилеву!","13":"И поймете вы, что Я – Господь, когда открою ваши могилы, когда выведу вас из могил, о Мой народ!","14":"Мой дух Я вложу в вас, и вы оживете. Я дарую вам мирную жизнь на вашей земле, и вы поймете, что Я – Господь Бог. Так Я сказал и так Я сделаю! – говорит Господь Бог\"».","15":"И было мне слово Господа:","16":"«Человек! Возьми дощечку и напиши на ней „Иуда и сыны Израилевы, что в союзе с ним\". Потом возьми другую дощечку и напиши на ней: „Иосиф и весь народ Израилев, что в союзе с ним\"(это дощечка племени Ефрема).","17":"И приложи их друг к другу, чтобы получилась одна дощечка, чтобы стали они в твоей руке единым целым.","18":"И когда сыновья твоего народа спросят тебя: „Объясни, что это зна – чит?\",","19":"скажи им: „Так говорит Господь Бог: Я возьму дощечку Иосифа и племен Израилевых, которые в союзе с ним (ныне она в руке Ефрема), и приложу к ней дощечку Иуды, чтобы получилась единая дощечка. Одним целым они будут в Моей руке\".","20":"Эти две дощечки, на которых ты сделал надписи, держи в руке у всех на виду","21":"и скажи: „Так говорит Господь Бог: Я уведу сынов Израилевых из владений чужих народов, к которым они пришли, соберу их отовсюду и приведу назад в их страну.","22":"Там, на горах Израилевых, Я сделаю их единым народом, и один царь будет царствовать над всеми ними. И не будут больше они двумя народами, не будут больше разделяться на два царства.","23":"Не будут больше оскверняться идолами своими, мерзостями и преступлениями. Я спасу их от отступничества, в которое они впали, Я очищу их, и станут они Моим народом, а Я буду – их Богом.","24":"Раб Мой Давид будет царем над ними, один пастух будет над всеми ними. Они будут жить по Моим предписаниям, Мои законы будут соблюдать и исполнять их.","25":"И будут жить они на этой земле, которую Я даровал рабу Моему Иакову и на которой жили их отцы. Там они будут жить – и дети их, и дети детей – вовеки! И раб Мой Давид вовеки будет вождем их.","26":"Я заключу с ними договор, который принесет им благоденствие, и договор этот будет вечным. Я их сделаю многочисленными, и навеки Я поставлю среди них Мое святилище.","27":"Там Я буду пребывать с ними. Я буду их Богом, а они будут Моим народом.","28":"И святилище Мое будет вечно пребывать среди них – и тогда поймут народы, что Я, Господь, посвятил Израиль Себе!\"»"},"38":{"1":"И было мне слово Господа:","2":"«Человек! Обрати свой взор против Гога, против земли Магога, против главного вождя Мешеха и Тувала и произнеси пророчество против него.","3":"Скажи: „Так говорит Господь Бог: Я иду к тебе, Гог, главный вождь Мешеха и Тувала!","4":"Я заставлю тебя пойти в другую сторону, вставив крюк тебе в челюсть, и поведу тебя и все твои полчища – лошадей и всадников в полном боевом облачении, несметное множество людей с броней и щитами, с мечами в руках,","5":"персов, кушитов и ливийцев со щитами и шлемами,","6":"Гомера с его полками и род Тогармы с хребтов Севера с его полками – все бесчисленные народы, что идут за тобою.","7":"Вставай, снаряжайся вместе со всем своим войском, что собралось вокруг тебя, ты будешь надсмотрщиком над ними!","8":"Спустя многие годы ты будешь призван! В те грядущие годы ты пойдешь на землю, возрожденную после войны, – ее жители после рассеяния среди многочисленных народов собрались на пустовавших горах Израилевых, вернулись из рассеяния среди народов и стали жить, ничего не опасаясь.","9":"Ты поднимешься словно гроза, придешь словно туча, застилая всю землю, – ты и все полчища твои и несметные народы, что идут за тобой.","10":"Так говорит Господь Бог: в те дни придет тебе в голову замысел, ты задумаешь злое дело.","11":"Ты скажешь:, Пойду против страны беззащитной, нападу на людей безмятежных, что живут, ничего не опасаясь. Нет у них ни крепостных стен, ни засовов, ни ворот.","12":"Ты устроишь набег, возьмешь добычу, обрушишь руку свою на селения, восставшие из руин, на народ, что вернулся из рассеяния и ныне владеет скотом и добром и живет на Пупе Земли.","13":"И Сава, и Дедан, и купцы Таршиша, все его торговцы будут приветствовать тебя:, Ты пришел за добычей! Для грабежа собрал войско! Чтобы забрать серебро и золото, скот и добро, чтобы устроить грабеж великий!'\"","14":"Произнеси пророчество, человек, скажи Гогу: „Так говорит Господь Бог: в то время народ Мой Израиль будет жить, ничего не опасаясь. Но ты поднимешься","15":"и выйдешь из своей страны, сойдешь с хребтов Севера, а вместе с тобой – бесчисленные народы на конях, великое войско, несметная сила.","16":"И пойдешь ты против народа Моего Израиля, словно туча, застилая землю. В те грядущие дни Я поведу тебя против Моей земли, чтобы народы поняли, кто Я: ибо Я явлю им Мою святость через то, что сделаю с тобой, Гог, у них на глазах!","17":"Так говорит Господь Бог: ты тот, о ком Я издревле говорил через Моих рабов, пророков Израилевых. Они пророчествовали в те далекие дни и годы, что ты будешь приведен против народа Израилева.","18":"Но в тот день, когда придет Гог на страну Израилеву, – говорит Господь Бог, – разгорится Мой яростный гнев.","19":"В ярости Моей, в огне Моего гнева Я говорю: в тот день великое землетрясение будет в стране Израилевой.","20":"И затрепещут предо Мною рыбы морские и птицы небесные, и дикие звери, и все твари, которыми кишит земля, и все люди на земле. Обрушатся горы, падут скалы, и все стены рухнут на землю.","21":"По всем горам Моим Я призову на него меч, – говорит Господь Бог, – и брат поднимет меч на брата.","22":"И Я совершу суд над ним, покараю мором и кровью. Ливень, все смывающий, и каменный град, огонь и серу Я обрушу на него и на полчища его и на бесчисленные народы, что идут за ним.","23":"И явлю величие Мое и святость Мою, явлю Себя пред очами несметных народов, и поймут они, что Я – Господь\"."},"39":{"1":"А ты, человек, произнеси пророчество против Гога. Скажи: „Так говорит Господь Бог: Я иду к тебе, Гог, главный вождь Мешеха и Тувала!","2":"Я заставлю тебя пойти в другую сторону, поведу тебя на веревке, Я заставлю тебя сойти с хребтов Севера и приведу тебя на горы Израилевы.","3":"И Я выбью лук из твоей левой руки, вырву стрелы из твоей правой руки.","4":"На горах Израилевых ты падешь вместе со своими полчищами, вместе с народами, что идут за тобой. Стервятникам, всем птицам крылатым и диким зверям Я отдам тебя на съедение.","5":"В чистом поле ты падешь, так сказал Я, Господь, – говорит Господь Бог. –","6":"Я пошлю огонь на Гога, на тех, кто ничего не опасаясь, живет в странах приморских, и поймут они, что Я – Господь.","7":"И святое имя Мое Я явлю среди Моего народа, Израиля, и не позволю впредь, чтоб святое имя Мое бесславили. И поймут народы, что Я – Господь, Святой Израилев.","8":"Придет, наступит, – говорит Господь Бог, – тот день, предреченный Мною.","9":"И выйдут жители городов Израилевых и разведут огонь и будут жечь оружие – щиты и броню, луки и стрелы, дубины и копья. Семь лет они будут жечь оружие.","10":"И не нужно будет носить дрова с поля, собирать их в лесу, ибо оружие будет вместо дров. И ограбят они тех, кто грабил их, захватят добычу у тех, кто у них брал добычу, – говорит Господь Бог. –","11":"В те дни Я выделю Гогу место в Израиле – могилу в долине Оверим, что к востоку от моря (идущим она перекроет дорогу). Похоронят там Гога и все полчища его и назовут то место долиной Хамон – Гог.","12":"Семь месяцев будет народ Израилев хоронить их, чтобы очистить страну.","13":"Весь народ страны будет участвовать в погребении, и день, когда Я явлю им Мое величие, станет для них днем славы, – говорит Господь Бог. –","14":"Назначат людей, которые будут обходить страну и погребать мертвецов, лежащие на земле останки, чтобы очистить страну. В течение семи месяцев они будут вести поиски.","15":"Они будут обходить страну и, если где увидят человеческие кости, будут устанавливать специальный знак, чтобы могильщики погребли останки в долине Хамон – Гог.","16":"(И город тоже назовется Хамона.) Вот так будет очищена вся страна\".","17":"А ты, человек, – так говорит Господь Бог, – скажи птицам крылатым и зверям диким: „Приходите, стекайтесь отовсюду, собирайтесь на пир, который Я для вас приготовил, на великий пир на горах Израилевых! Ешьте мясо и пейте кровь!","18":"Мясо могучих воинов вы будете есть, кровь вождей земных будете пить. Все они – словно овны и бараны, козлы и быки, откормленные в Башане.","19":"Досыта наедитесь вы жиром, допьяна напьетесь кровью на пиру Моем, который Я для вас приготовил.","20":"За Моим столом вы насытитесь лошадьми и колесничими, силачами и воинами, – говорит Господь Бог\".","21":"Я явлю народам Мою славу, и все народы увидят, как Я вершу суд и как налагаю на них руку Мою.","22":"И поймет народ Израилев, что Я, Господь, – их Бог, отныне и вовеки.","23":"И поймут народы, что за грехи свои был отправлен народ Израилев в изгнанье, за преступления, совершенные против Меня. Потому Я отвернулся от него и отдал народ Израилев в руки врагов, и он погибал от меча.","24":"Из-за нечистоты его и преступлений его Я поступил с ним так – отвернулся от него.","25":"Но так говорит Господь Бог: ныне Я верну Иакова из изгнания, смилуюсь над народом Израилевым! Я буду ревностно защищать имя Мое святое!","26":"И когда они будут жить на своей земле в безопасности и никто не будет им страшен, будут они стыдиться своих позорных поступков и тех преступлений, которые они совершали против Меня.","27":"Я верну их от народов, Я соберу их из вражеских стран. Так Я явлю святость Мою – через то, что совершу с ними на глазах у многочисленных народов!","28":"И когда Я, отправив их сперва к народам в изгнание, вновь соберу их в их собственной стране, тогда поймут они, что Я, Господь, – их Бог. И никого из них Я не оставлю впредь на чужбине.","29":"И никогда больше Я не отвернусь от них, ибо Я излил Мой дух на народ Израилев, – говорит Господь Бог»."},"40":{"1":"В начале двадцать пятого года нашего изгнания, в десятый день месяца (это был четырнадцатый год после разрушения города), в тот самый день Господь простер надо мной Свою руку и перенес меня в ту страну –","2":"на землю Израилеву Он перенес меня в видениях Божьих и поставил на высокой горе. И на этой горе, на южной ее стороне, – силуэты городских зданий.","3":"Он перенес меня туда – и я увидел, что в воротах стоит некто. Казалось, будто он медный. В руках у него были льняной шнур и мерная трость.","4":"Он сказал мне: «Человек! Смотри и слушай, вникай во все, что я покажу тебе, ибо для того ты и перенесен сюда, чтобы я показал тебе это. Все, что увидишь, расскажи народу Израилеву!»","5":"И вот я увидел, что Храм со всех сторон опоясан стеной. Мерная трость в руках у моего проводника имела в длину шесть больших локтей, которые на ладонь длиннее обычного локтя. Проводник измерил стену. Она была толщиной в одну трость и высотой в одну трость.","6":"Затем он подошел к восточным воротам, поднялся по их ступеням и измерил порог ворот: его протяженность вглубь ворот – одна трость (протяженность другого порога вглубь ворот была тоже одна трость).","7":"Каждая из боковых комнат была длиной в одну трость и шириной в одну трость; простенок между комнатами – пять локтей. Порог возле притвора, примыкавшего к воротам с внутренней стороны, был протяженностью в одну трость.","8":"Проводник измерил притвор – получилось восемь локтей, а ширина торцов его наружной стены – два локтя. Притвор примыкал к воротам с внутренней стороны.","10":"Внутри восточных ворот, по одну и другую руку от входа, было по три комнаты. Все они были одного размера, и простенки между комнатами с обеих сторон – тоже одного размера.","11":"Проводник измерил проем ворот – десять локтей. Ширина же внутреннего коридора ворот – тринадцать локтей.","12":"Перед комнатами находилась перегородка в один локоть – и по другую сторону коридора тоже перегородка в один локоть. А сами комнаты с той и другой стороны от коридора имели по шесть локтей в ширину.","13":"Проводник измерил ширину всего помещения ворот от задней стены одной комнаты до задней стены другой комнаты – получилось двадцать пять локтей (проходы в комнаты находились друг напротив друга).","14":"Расстояние от входа в ворота и до выхода со стороны притвора – пятьдесят локтей.","16":"В помещениях ворот, в боковых комнатах и на простенках между ними, по всему периметру, изнутри были сделаны ниши в форме окон. Такие же ниши были сделаны по все – му периметру изнутри притвора. На его торцах были сделаны пальмы.","17":"Проводник провел меня во внешний двор – там были служебные помещения. По всему периметру двора шел каменный помост, и на этом помосте располагались тридцать служебных помещений.","18":"Помост примыкал вплотную к боковым стенам ворот, его ширина была такой же, как у ворот. Это нижний помост.","19":"Проводник измерил расстояние от нижних ворот до границ внутреннего двора – сто локтей (это расстояние было одинаковым и от восточных ворот, и от северных).","20":"Затем он измерил длину и ширину северных ворот внешней стены.","21":"И боковые комнаты в них (по три с каждой стороны коридора), и простенки между комнатами, и притвор – все было таким же, как у первых ворот. В длину ворота были пятьдесят локтей, в ширину – двадцать пять.","22":"И ниши в форме окон, и притвор, и пальмы были такого же размера, как у восточных ворот. Спереди к воротам вели семь ступеней, позади – примыкал притвор.","23":"Напротив северных и восточных ворот внешнего двора находились ворота во внутренний двор. Расстояние между внешними и внутренними воротами – сто локтей.","24":"Проводник повел меня на южную сторону, к южным воротам. Он измерил их – размеры торцов и притвора были такими же, как у остальных ворот.","25":"Внутри южных ворот и притвора были такие же ниши в форме окон по всему периметру, как у остальных ворот. Пятьдесят локтей была длина ворот, ширина – двадцать пять.","26":"Спереди к воротам вели семь ступеней, позади – примыкал притвор. На его торцах, с той и другой стороны от входа, было сделано по пальме.","27":"Были в стене внутреннего двора и южные ворота. Проводник измерил расстояние от внешних южных ворот до внутренних – оно было сто локтей.","28":"Через южные внутренние ворота он провел меня во внутренний двор. Он измерил южные внутренние ворота – их размеры были такими же, как у остальных ворот.","29":"И боковые комнаты, и простенки между ними, и притвор – все было таких же размеров. Такие же ниши в виде окон были сделаны по периметру ворот и притвора. Пятьдесят локтей была длина ворот, ширина – двадцать пять.","30":"Притвор выходил на внешний двор, на его торцах были сделаны пальмы. К воротам вели восемь ступеней.","32":"Проводник провел меня во внутренний двор через восточные внутренние ворота. Он измерил эти ворота – их размеры были такими же, как у остальных ворот.","33":"И боковые комнаты, и простенки между ними, и притвор – все было таких же размеров. Такие же ниши в виде окон были сделаны по периметру ворот и притвора. Длина ворот была пятьдесят локтей, ширина – двадцать пять.","34":"Притвор выходил во внешний двор; на его торцах, с той и другой стороны от входа, были сделаны пальмы. Восемь ступеней вели к воротам.","35":"Проводник провел меня через северные внутренние ворота и измерил их – размеры их были такими же, как у остальных ворот.","36":"И боковые комнаты, и простенки между ними, и притвор были такими же. Такие же ниши в виде окон были сделаны по периметру ворот. Длина ворот была пятьдесят локтей, ширина – двадцать пять.","37":"Притвор был обращен во внешний двор, на его торцах, с той и другой стороны от входа, были сделаны пальмы. Восемь ступеней вели к воротам.","38":"Возле ворот было помещение, вход в него был через притвор; там омывают части туш, предназначенные для всесожжения.","39":"А в притворе ворот стояли столы, два с одной стороны и два с другой, на них разделывают животных для всесожжении, для очистительных и возместительных жертв.","40":"И снаружи, возле лестницы, ведущей к северным воротам, у одной боковой стены притвора стояли два стола и у другой боковой стены стояли два стола.","41":"Итого, четыре стола стояли близ одной боковой стены, по одну сторону от входа, и четыре стола близ другой боковой стены, по другую сторону от входа; всего – восемь столов. На них разделывали жертвенных животных.","42":"Те четыре стола, что у лестницы, были сделаны из тесаного камня. Длина их – полтора локтя, ширина – полтора локтя, высота – локоть. На этих столах лежали орудия, которыми разделывают животных для всесожжении и прочих жертвоприношений.","43":"По всему периметру помещения в стену были вбиты крючья, каждый размером с ладонь. На столах лежало мясо жертвенных животных.","44":"За внутренними воротами, на внутреннем дворе, находились два ряда служебных помещений. Один ряд примыкал к боковой стене северных ворот, входы в эти помещения были обращены к югу. Другой ряд примыкал к боковой стене южных ворот, входы в эти помещения были обращены к северу.","45":"Проводник сказал мне: «Помещения, что обращены входом к югу, предназначены для священников, которые несут службу в Храме.","46":"Помещения, что обращены входом к северу, предназначены для священников, которые несут службу при жертвеннике. Все они потомки Цадока, и лишь они одни из всех потомков Левия могут приближаться к Господу, чтобы служить Ему».","47":"Проводник измерил внутренний двор. Двор был квадратным, сто локтей в длину и сто локтей в ширину. Перед Храмом стоял жертвенник.","48":"Проводник подвел меня к притвору Храма и измерил торцы его наружной стены – оба торца были по пять локтей в ширину. Ширина входа составляла четырнадцать локтей, а длина стен по бокам от входа – по три локтя.","49":"Ширина притвора была двадцать локтей, глубина – двенадцать. Десять ступеней вели к притвору. Возле торцов наружной стены притвора находились два столба, один по одну руку от входа, другой – по другую."},"41":{"1":"Проводник провел меня в храмовый зал и измерил ширину торцов его наружной стены; с той и другой стороны от входа торцы имели в ширину по шесть локтей.","2":"Ширина входа в храмовый зал – десять локтей; длина стен по бокам от входа – по пять локтей. Проводник измерил длину храмового зала, она составляла сорок локтей; ширина – двадцать локтей.","3":"Проводник подошел ко входу во внутреннее помещение и измерил торцы его стен. Они имели в ширину по два локтя. Ширина входа – шесть локтей, длина стен по бокам от входа – по семь локтей.","4":"Проводник измерил внутреннее помещение: оно имело двадцать локтей в дли – ну и двадцать в ширину (как и храмовый зал). Проводник сказал мне: «Это – святыня святынь».","5":"Проводник измерил толщину стены Храма – шесть локтей. Ширина же боковых комнат, которые окружали Храм, составляла четыре локтя.","6":"Эти комнаты располагались одна над другой – тридцать комнат в три яруса. Стена Храма спускалась вниз уступами, и перекрытия комнат, окружавших Храм, покоились на этих уступах; балки перекрытий не были вделаны в стену Храма.","7":"На верхний ярус с нижнего вела лестница, которая проходила через средний ярус.","8":"Я увидел, что Храм расположен на высокой платформе, которая со всех сторон выступает за его стены; она служит фундаментом и для боковых комнат. Высота ее – одна трость, то есть шесть больших локтей.","9":"Внешняя стена боковых комнат имела пять локтей в толщину. Между платформой, на которой находились боковые комнаты Храма,","10":"и служебными помещениями шел открытый проход шириной в двадцать локтей (вокруг всего Храма был открытый коридор).","11":"Боковые комнаты имели два выхода на выступающую часть храмовой платформы: один с северной стороны, другой – с южной. Ширина этой выступающей вокруг Храма части была пять локтей.","12":"С западной стороны к открытому коридору за Храмом примыкало строение; ширина его внутреннего помещения – семьдесят локтей. Толщина всех его стен – по пять локтей, длина его внутреннего помещения – девяносто локтей.","13":"Проводник измерил длину всего Храма; она была сто локтей. Открытый коридор позади Храма и строение за Храмом (с учетом толщины стен строения) вместе занимали также сто локтей.","14":"Ширина площади перед входом в Храм с восточной стороны – также сто локтей.","15":"Проводник измерил строение, которое выходило на открытый коридор позади Храма. Длина строения составляла сто локтей; с той и другой стороны к нему примыкали галереи. Храмовый зал, внутреннее помещение и притвор, выходящий на двор,","16":"были облицованы деревом. И ниши в виде окон, и трехъярусные галереи по периметру – все было покрыто деревом, от порога и пола до окон (это были глухие окна)","17":"и до притолоки над входом. Во внутреннем помещении Храма и во внешнем, по всему периметру стен внутреннего и внешнего помещений, были сделаны изображения","18":"херувимов и пальм. Между каждыми двумя херувимами было по пальме. У херувимов было по два лица;","19":"с одной стороны к пальме обращено человеческое лицо херувима, с другой – львиное. Так было сделано по всему периметру Храма.","20":"Изображения херувимов и пальм покрывали стену храмового зала от пола до притолоки над входом.","21":"Рамы дверей в храмовом зале были четырехступенчатыми. Перед Святилищем находилось нечто, похожее","22":"на деревянный жертвенник, высотой в три локтя, длиной в два локтя и шириной в два локтя. Его углы, подножие и стенки были сделаны из дерева. Проводник сказал мне: «Это стол, стоящий пред лицом Господа».","23":"Двери в храмовый зал и двери в Святилище – обе были двустворчатыми.","24":"Каждая из створок в свою очередь состояла из двух частей: обе части поворачиваются на петлях. Две части были у одной створки и две – у другой.","25":"И были на дверях зала изображены херувимы и пальмы, такие же, как на стенах. Над входом в притвор, снаружи, шел деревянный карниз.","26":"На боковых стенах притвора, с той и другой стороны, а также на стенах боковых комнат и на карнизе были сделаны ниши в виде окон и изображения пальм."},"42":{"1":"Проводник вывел меня во внешний двор через северные ворота и подвел к служебному помещению, которое задней своей стеной частично примыкало к открытому коридору за Храмом, частично – к северной стене строения, что позади Храма.","2":"Общая длина его фасада составляла сто локтей, входы в него были обращены на север. Ширина здания – пятьдесят локтей.","3":"Оно располагалось между открытым коридором шириной в двадцать локтей, что во внутреннем дворе, и помостом, что во внешнем дворе. Оно было трехэтажным, галереи располагались одна над другой.","4":"Перед помещениями шел огороженный коридор; его ширина – десять локтей, длина – сто локтей. Входы в служебные помещения были обращены на север.","5":"Верхние помещения были уже нижних, потому что часть их площади занимали галереи. Здание сужалось кверху – от нижнего этажа к среднему, от среднего к верхнему.","6":"Оно было трехэтажным; галереи не имели таких колонн, как во дворах, и поэтому здание сужалось кверху: от нижнего этажа к среднему, от среднего к верхнему.","7":"Со стороны внешнего двора перед этим зданием шла ограда. Длина ее – пятьдесят локтей.","8":"Поскольку длина тех служебных помещений, что были расположены по периметру внешнего двора, также равнялась пятидесяти локтям, то общая длина коридора перед зданием составляла сто локтей.","9":"К помещениям на первом этаже этого здания можно было пройти с востока, из внешнего двора, через вход,","10":"находившийся у начала ограды. С южной стороны от открытого коридора за Храмом и строения позади Храма находились такие же служебные помещения,","11":"а перед ними – такой же огороженный коридор. Помещения выглядели так же, как и на северной стороне, такой же была их длина и ширина, такое же расположение входов и выходов.","12":"Ко входам в южные служебные помещения можно было пройти с востока, через вход у начала коридора, образованного оградой.","13":"Проводник сказал мне: «Помещения, что с севера и юга примыкают к открытому пространству вокруг Храма, – священные помещения. Там священники, которым разрешено приближаться к Господу, едят жертвы, что являются святыней святынь. Туда они относят жертвы, что являются святыней святынь: хлебные приношения, очистительные жертвы и возместительные жертвы. Это место свято!","14":"Если священники войдут в Святилище, то прежде, чем выйти из Святилища во внешний двор, они должны оставить в этих помещениях те одежды, в которых совершали богослужение, ибо одежды эти святы. Священники должны сменить одежду, и только после этого идти туда, где дозволено быть народу».","15":"Проводник закончил измерения внутри храмового комплекса, вывел меня наружу через восточные ворота и стал измерять длину стен.","16":"Мерной тростью он измерил восточную сторону – в ней было пятьсот локтей. Затем он повернул","17":"и измерил северную сторону – в ней было пятьсот локтей. Затем он вернулся","18":"и измерил южную сторону – в ней было пятьсот локтей.","19":"Затем он повернул к западной стороне и измерил ее – в ней было пятьсот локтей.","20":"Со всех четырех сторон, кругом он измерил внешнюю стену. Со всех сторон протяженность стены была по пятьсот локтей. Стена отделяла священное от несвященного."},"43":{"1":"Он подвел меня к восточным воротам.","2":"И я увидел, что с востока приближается Слава Бога Израилева. И послышался гул – словно гул бушующего моря, и вся земля засверкала от Славы Его.","3":"Это видение было таким же, как и то, что я видел, когда Он приходил уничтожить город – и такое же видение я видел при реке Кевар. Я пал ниц.","4":"Слава Господня вошла в Храм через восточные ворота.","5":"Дух поднял меня и перенес на внутренний двор. И я увидел, как Слава Господня наполнила Храм.","6":"И услышал я голос изнутри Храма (а проводник в это время находился рядом со мной).","7":"И Он сказал мне: «Человек! Вот место для престола Моего, подножие для стоп Моих! Здесь, среди сынов Израилевых, Я поселюсь навеки. И пусть народ Израилев – и народ, и цари его – впредь не бесславят Мое святое имя развратом своим, погребальными жертвами усопшим царям!","8":"Они строили свой порог возле Моего порога, свои двери – возле Моих дверей, лишь стена была между Мной и ними! И бесславили они имя Мое святое теми мерзостями, которые совершали. Потому Я и уничтожил их во гневе.","9":"Пусть же сыны Израилевы уберут прочь с глаз Моих этот разврат – погребальные жертвы царям – и тогда Я поселюсь среди них навеки!","10":"Человек! Расскажи народу Израилеву об этом Храме, пусть устыдятся они своих мерзостей и исчислят план этого Храма.","11":"И если они устыдятся всего того, что совершали, то опиши им образ Храма и его план, все его входы и выходы, образ его и предписания о нем, образ его и весь устав его. Запиши все это у них на глазах, и пусть они будут верны этому образу и всем предписаниям, и воплотят их в жизнь.","12":"Таков закон о Храме: вершина горы и все, что вокруг, – это святыня святынь! Это закон о Храме».","13":"Вот размеры жертвенника в локтях (в больших локтях, которые на ладонь длиннее обычного локтя). Желоб – глубиной в локоть и в локоть – шириной. Желоб со всех сторон окружен бортиком, размером в одну пядь. А высота жертвенника такая:","14":"расстояние ото дна желоба до нижнего уступа жертвенника – два локтя (ширина нижнего уступа – один локоть); от нижнего уступа до верхнего – четыре локтя (ширина верхнего уступа – локоть);","15":"высота верхнего яруса – очага – четыре локтя. Из очага выступают кверху четыре рога.","16":"Очаг имеет по двенадцать локтей в длину и ширину, по всем четырем сторонам; он квадратный.","17":"Площадка, на которой возведен очаг, имеет по четырнадцать локтей в длину и ширину, по всем четырем сторонам. Ее окаймляет бортик в пол – локтя шириной, образуя по всему периметру желоб в локоть глубиной. С восточной стороны примыкает лестница.","18":"И сказал Он мне: «Человек! Так говорит Господь Бог: вот повеление о жертвеннике. В день, когда его воздвигнут, чтобы совершать на нем всесожжения и окроплять его кровью,","19":"дай священникам – левитам из числа потомков Цадока, которым позволено приближаться ко Мне, – говорит Господь, – и служить Мне, дай им тельца для очистительной жертвы.","20":"И возьми кровь тельца и окропи ею четыре рога и четыре угла площадки и бортик вокруг желоба. Так очистишь жертвенник и совершишь над ним обряд искупления.","21":"И возьми тельца, принесенного в качестве очистительной жертвы, и сожги его в особом месте, вне Святилища.","22":"На другой день принеси в качестве очистительной жертвы козла без изъяна, и пусть совершают над жертвенником очищение так же, как это делали при жертвоприношении тельца.","23":"И после этой очистительной жертвы принеси в жертву тельца без изъяна и барана без изъяна.","24":"Принеси их в жертву Господу – пусть священники посыплют их солью и сожгут их как жертву всесожжения Господу.","25":"Каждый день в течение семи дней приноси козла в качестве очистительной жертвы. И каждый день пусть приносят в жертву тельца без изъяна и барана без изъяна.","26":"Семь дней пусть совершают над жертвенником обряд искупления и очистят его, и освятят.","27":"А после этого, на восьмой день и далее, священники могут приносить на жертвеннике ваши жертвы – всесожжения и пиршественные жертвы, чтобы Я был к вам благосклонен», – говорит Господь Бог."},"44":{"1":"Он повел меня обратно, к внешним восточным воротам Храма. Они были заперты.","2":"И сказал мне Господь: «Эти ворота будут заперты и не откроются, и не пройдет через них человек. Господь Бог Израилев прошел через них, и потому они будут заперты.","3":"И лишь правитель, только правитель может воссесть в них, чтобы совершить трапезу пред Господом. Он должен входить в них через притвор и таким же образом выходить обратно».","4":"Проводник через северные ворота провел меня к Храму. И я увидел, что Храм Господа наполнен Славой Господней. Я пал ниц.","5":"И сказал мне Господь: «Человек! Внимай, смотри и слушай! Запомни все то, что Я говорю тебе об уставах дома Господня и правилах его. Запомни, кто может войти в Храм, а кто должен покинуть Святилище.","6":"И скажи упрямому народу Израилеву: „Так говорит Господь Бог: хватит тебе творить мерзости, о народ Израилев!","7":"Тем, что вы привели в Святилище Мое чужаков, не обрезанных ни сердцем, ни плотью, вы оскверняете Святилище Мое! И это в то время, как вы приносите Мне пищу Мою – жир и кровь! Мерзостями своими вы нарушили договор со Мною.","8":"Вместо того, чтобы самим нести службу в Святилище Моем, вы сделали служителями при Святилище Моем чужеземцев.","9":"Так говорит Господь Бог: никто из чужеземцев, необрезанных сердцем и плотью, не должен входить в Мое Святилище, в том числе и те чужеземцы, что живут среди сынов Израилевых.","10":"А левиты, что покинули Меня, отступились от Меня во время отступничества Израилева и стали служить своим идолам, понесут наказание за свое преступление.","11":"Они станут прислужниками при Моем Святилище, будут нести стражу при храмовых воротах и прислуживать в Храме. Они будут закалывать животных, приводимых народом для всесожжении и жертв. Они будут, как слуги, прислуживать народу.","12":"Они прислуживали народу перед идолами их, они ввели народ Израилев в гибельный грех, вот за это Я занесу на них Мою руку, – говорит Господь Бог, – и понесут они наказание за свое преступление!","13":"Не будут они впредь приближаться ко Мне, не будут Моими священниками, не будут приближаться к Моим святыням и к святыне святынь! Понесут они свой позор и наказание за все мерзости, которые совершали.","14":"Я велю им прислуживать в Храме, возложу на них обязанности по всем работам в Храме.","15":"Лишь священникам – левитам из потомков Цадока, которые продолжали служить в Святилище Моем в то время, как сыны Израилевы от Меня отступились, лишь им будет позволено приближаться ко Мне. Они будут служить Мне, будут предстоять предо Мною, чтобы приносить Мне жир и кровь, – говорит Господь Бог. –","16":"Они будут входить в Мое Святилище и будут прислуживать за Моим столом, будут совершать богослужение Мне.","17":"Когда священники входят в ворота внутреннего двора, они должны быть одеты в льняные одежды. Ничего шерстяного не должно быть на них во время богослужения в воротах внутреннего двора и в Храме.","18":"На головах у них должны быть льняные повязки, на бедрах – льняные штаны. Священники не должны опоясываться ничем таким, от чего могли бы вспотеть.","19":"Перед тем как выйти на внешний двор, к народу, они должны снять с себя одежды, в которых служили, оставить их в служебных помещениях при Святилище и облачиться в другие одежды, чтобы народ через их одежду не соприкоснулся со священным.","20":"Священники не должны брить головы, но не должны и отпускать длинных волос, они должны стричь волосы.","21":"Ни один священник не должен пить вина перед тем, как войти на внутренний двор.","22":"В жены священники не должны брать ни вдовы, ни разведенной, но только девицу из народа Израилева, или же вдову священника могут они взять в жены.","23":"Пусть они учат Мой народ тому, что есть священное, а что несвященное, пусть объясняют народу Моему, что чисто, а что нечисто.","24":"Священники должны разбирать судебные тяжбы и судить по Моим законам. Они должны исполнять все наставления Мои, все предписания о праздниках Моих и свято чтить субботу.","25":"Священник не должен оскверняться приближением к мертвому телу. Только ради отца, матери, сына, дочери, брата или сестры, если она не была замужем, может он допустить такое осквернение.","26":"После этого, совершив обряд очищения, он обязан ждать еще семь дней,","27":"а затем, когда пойдет к Святилищу, на внутренний двор, чтобы нести службу при Святилище, он должен принести очистительную жертву, – говорит Господь Бог.","28":"А что касается надела священников – Я Сам буду их наделом. Не давайте им земельных владений в Израиле, ибо Я Сам – их надел!","29":"Хлебные приношения, очистительные жертвы и возместительные жертвы будут их пропитанием, и все заклятое в Израиле принадлежит священникам.","30":"Первины всякого урожая, любое приношение из всех приношений ваших – все это принадлежит священникам. И первую выпечку из муки нового урожая отдавайте священнику – и тогда пребудет благословение на доме твоем.","31":"Священники не должны есть мясо птиц или животных, которые издохли или были задраны дикими зверьми."},"45":{"1":"Когда вы будете делить землю на наделы, отделите в этой стране как дар Господу – обособленный священный участок, двадцать пять тысяч локтей в длину и в ширину – двадцать тысяч. Эта земля будет священной на всем своем протяжении.","2":"(Для Святилища там будет отведен квадратный участок пятьсот локтей на пятьсот локтей, вокруг него должна быть еще полоса пастбищ шириной в пятьдесят локтей.)","3":"Из этого обособленного участка выдели полосу земли двадцать пять тысяч локтей в длину и десять тысяч локтей в ширину: здесь будет находиться Святилище, святыня святынь.","4":"Это – священная часть страны. Она будет принадлежать священникам, что несут службу в Святилище, – тем, кто приближается к Господу, чтобы служить Ему. Здесь будет им место для домов, здесь же будет и Святилище.","5":"Оставшаяся территория в двадцать пять тысяч локтей в длину и десять тысяч локтей в ширину будет принадлежать левитам, что прислуживают в Храме. Это их владение, здесь будут города, в которых они станут жить.","6":"Подле священного участка выделите во владение Городу территорию шириной в пять тысяч локтей и длиной в двадцать пять тысяч локтей. Этой землей сообща будет владеть весь народ Израилев.","7":"С той и другой стороны от священного участка и от владений Города – земля правителя. Она будет простираться к западу от западной границы священного участка и владений Города, а также к востоку от их восточной границы. В длину эти земли будут такими же, как наделы племен Израилевых – будут простираться от западной до восточной границы страны.","8":"Таков будет надел правителя в стране Израилевой, чтобы вожди израильские не притесняли больше Мой народ, чтобы разделили землю среди племен Израилевых.","9":"Так говорит Господь Бог: хватит, вожди Израилевы! Прекратите грабеж и насилие! Вершите справедливый суд, перестаньте сгонять Мой народ с его земли, – говорит Господь Бог.","10":"Пусть будут у вас правильные весы, правильная эфа и правильный бат.","11":"Эфа и бат должны быть одинаковыми. Бат – десятая часть хомера, и эфа – десятая часть хомера. И для эфы, и для бата эталон – хомер.","12":"В шекеле – двадцать гер. Двадцать шекелей да двадцать пять шекелей, да пятнадцать шекелей будут у вас составлять одну мину.","13":"Вот какие приношения вы должны приносить: шестую часть эфы с каждого хомера пшеницы и шестую часть эфы с каждого хомера ячменя;","14":"оливкового масла нужно давать, в батах, одну десятую бата с каждого кора (кор, как и хомер, содержит десять бат);","15":"а из стад Израилевых нужно отдавать одну овцу с каждых двухсот овец. Таковы приношения для хлебных жертв, жертв всесожжении, пиршественных жертв, чтобы совершать за народ искупительные обряды, – говорит Господь. –","16":"Весь народ должен доставлять эти приношения правителю Израиля.","17":"На правителе лежит обязанность обеспечивать всесожжения, хлебные приношения и возлияния во время празднеств, в новолуния и субботы – во все праздничные дни народа Израилева. Он будет обеспечивать очистительные жертвы и хлебные приношения, жертвы всесожжения и пиршественные жертвы, чтобы могли совершаться искупительные обряды за народ Израилев.","18":"Так говорит Господь Бог: в первый месяц, в первый его день возьми быка без изъяна и соверши очищение Святилища.","19":"Пусть священник возьмет крови очистительной жертвы и окропит ею дверные косяки в Храме, четыре угла нижнего яруса жертвенника и косяки ворот внутреннего двора.","20":"Так же поступи на седьмой день этого месяца – за всякого, кто совершил грех неумышленно или по незнанию. Так вы совершите обряд искупления над Храмом.","21":"В первый месяц, на четырнадцатый день месяца будет у вас праздник Пасхи. Пусть семь дней едят пресный хлеб.","22":"В этот день пусть правитель в качестве очистительной жертвы за себя и за весь народ принесет в жертву быка.","23":"В течение семи дней праздника он должен совершать жертву всесожжения Господу – семь быков и семь баранов без изъяна – каждый день в течение семи дней. И еще пусть он каждый день в качестве очистительной жертвы приносит в жертву козла.","24":"Что касается хлебных приношений, они такие: одна эфа муки с каждым быком и одна эфа муки с каждым бараном, а на каждую эфу муки полагается один гин оливкового масла.","25":"Начиная с пятнадцатого дня седьмого месяца, на празднике, он должен в течение семи дней совершать такие же жертвоприношения: такие же очистительные жертвы, такие же всесожжения, такие же хлебные приношения и такие же приношения оливкового масла."},"46":{"1":"Так говорит Господь: восточные ворота внутреннего двора будут заперты в течение шести рабочих дней. А в день субботний пусть будут открыты и в день новолуния пусть будут открыты.","2":"И войдет правитель в притвор ворот, со стороны внешнего двора, и встанет у косяка ворот, а священники совершат от его имени всесожжение и принесут пиршественные жертвы. Пусть правитель совершит поклонение на пороге ворот и выйдет. А ворота до вечера будут не заперты.","3":"И народ пусть в субботы и в новолуния совершает возле этих ворот поклонение перед Господом.","4":"В день субботний правитель должен принести Господу в жертву всесожжения: шесть ягнят без изъяна и одного барана без изъяна.","5":"Его хлебное приношение должно быть таким: вместе с бараном одна эфа муки, а с каждым ягненком – столько муки, сколько правитель пожелает; и на каждую эфу муки полагается один гин оливкового масла.","6":"В праздник новолуния правитель должен принести в жертву всесожжения: одного быка без изъяна, шесть ягнят и одного барана – и ягнята, и баран должны быть без изъянов.","7":"Его хлебное приношение должно быть таким: одна эфа муки вместе с быком, одна эфа с бараном и с каждым ягненком – столько муки, сколько правитель пожелает; а на каждую эфу муки полагается один гин оливкового масла.","8":"Входить в ворота правитель должен через притвор и так же выходить из них.","9":"Во время праздников, когда народ страны приходит к Господу, чтобы совершить поклонение, пусть всякий, кто вошел через северные ворота, выходит через южные. Кто вошел через южные ворота, пусть выходит через северные. Никто не должен поворачивать назад и выходить через те же ворота, через которые вошел, а только через противоположные.","10":"Правитель пусть входит вместе с народом, когда входит народ, и выходит тогда, когда выходит народ.","11":"В праздники и торжественные дни хлебные приношения правителя должны быть таковы: одна эфа муки вместе с каждым тельцом, одна эфа вместе с каждым бараном, а с ягнятами – столько муки, сколько он пожелает. На каждую эфу муки полагается один гин оливкового масла.","12":"Если же правитель приносит всесожжения или пиршественные жертвы в качестве добровольных жертвоприношений Господу, то пусть откроют для него восточные ворота и совершат жертвоприношения так же, как в день субботний. Затем правитель должен покинуть ворота, и после того как он выйдет, ворота должны быть заперты.","13":"Ежедневно ты должен приносить Господу в жертву всесожжения годовалого ягненка без изъяна, каждое утро ты должен совершать эту жертву.","14":"Каждое утро вместе с ягненком приноси хлебное приношение – одну шестую часть эфы муки и треть гина оливкового масла, чтобы добавить его в пшеничную муку. Таково предписание навеки о регулярном хлебном приношении Господу.","15":"Пусть каждое утро приносят в жертву ягненка и совершают хлебное приношение с оливковым маслом – таков порядок регулярных всесожжении.","16":"Так говорит Господь Бог: если правитель выделяет землю кому-либо из своих сыновей, то это станет его наследственным наделом, владением, переходящим по наследству.","17":"Если же правитель выделяет землю из своих владений своему рабу, то она будет принадлежать рабу до года освобождения, а затем вернется к правителю. Лишь сыновьям может переходить земля правителя.","18":"И пусть правитель не присваивает себе землю народа, пусть никого не лишает надела. Сыновей он должен оделять землей из собственных владений, и никто из Моего народа не может быть изгнан из своего надела!\"»","19":"Затем проводник повел меня через проход сбоку от ворот к священным помещениям для священников, обращенным на север. В самом конце этих помещений, на западной стороне, было некое место.","20":"Он сказал мне: «Здесь священники должны варить возместительные жертвы и очистительные жертвы и печь хлебные жертвы, не вынося их на внешний двор, дабы народ не соприкоснулся со священным».","21":"Затем он вывел меня на внешний двор и подвел по очереди к каждому из четырех углов внешнего двора. И я увидел, что в каждом из углов двора есть огороженный участок.","22":"Во всех четырех углах внешнего двора были крытые огороженные участки – по сорок локтей в длину и тридцать в ширину. У всех четырех угловых участков были одни и те же размеры.","23":"Все четыре были обнесены стеной, внизу стены были устроены очаги.","24":"Проводник сказал мне: «Это поварни, здесь служители Храма будут варить жертвы, приносимые народом»."},"47":{"1":"После этого он повел меня назад, ко входу в Храм. И я увидел – из-под порога Храма течет ручей на восток (Храм был обращен входом на восток). Воды текли вниз по правую руку от Храма и к югу от жертвенника.","2":"Затем он вывел меня через северные ворота и повел снаружи в обход к восточным внешним воротам, и я увидел, что вода струится по правую руку от ворот.","3":"Проводник шел на восток, и в руках у него был мерный шнур. Он отмерил тысячу локтей и перевел меня через поток. Воды было по лодыжку.","4":"Он отмерил еще тысячу локтей и перевел меня через поток. Воды было по колено. Еще тысячу отмерил и перевел меня – воды было по пояс.","5":"Снова отмерил он тысячу локтей – там я уже не мог перейти: вода стояла так высоко, что можно было только плыть, а перейти поток по дну невозможно.","6":"Проводник сказал мне: «Запомни, человек, то, что ты видел!» Он повел меня обратно, к берегу потока.","7":"Когда я вновь оказался на суше, я увидел на обоих берегах потока великое множество деревьев. «Проводник сказал мне: «Воды этой реки текут к восточным областям страны, они спустятся к Араве и впадут в Соленое море, в загрязненные его воды, и те исцелятся.","9":"И там, куда придет поток, будут кишеть живые твари и будет великое множество рыбы. Ибо куда ни придут эти воды, они повсюду будут нести исцеление и жизнь.","10":"И будут стоять на берегу моря рыбаки, от Эн – Геди и до Эн – Эглаима будут они сушить свои сети, и будет там разной рыбы – словно в Великом море – не счесть.","11":"Но при этом болота и топи не станут пресными, они будут служить для добычи соли.","12":"Возле потока, на обоих его берегах, будут расти плодовые деревья всех видов. Листья их никогда не увядают, плоды никогда не кончаются. Каждый месяц деревья будут приносить новые плоды, ибо воды, которые их питают, текут из Святилища. Плоды деревьев будут употребляться в пищу, листья – для врачевания.","13":"Так говорит Господь Бог: вот границы, по которым вы распределите землю между двенадцатью племенами Израилевыми (а Иосифу – часть двойная).","14":"Все вы должны поровну владеть землею, о которой Я клялся, что дарую ее вашим отцам. Вам достанется эта земля во владение.","15":"Вот границы этой земли. На севере граница пойдет от Великого моря через Хетлон и Лево – Хамат к Цедаду,","16":"Бероте и Сивраиму, что лежит на стыке владений Дамаска и Хамата, а далее к Хацер – Хаттихону, что лежит на границе с Хаураном.","17":"Итак, граница пройдет от моря до Хацар – Энона, к северу от которого лежат владения Дамаска и Хамата. Такова северная граница.","18":"Восточная граница начинается посередине между Хаураном и Дамаском, идет между Галаадом и землей Израилевой – по Иордану – к Морю восточному, затем к Тамару. Такова восточная граница.","19":"Южная граница идет от Тамара к водам Мериват – Кадеша, а затем вдоль ложбины – к Великому морю. Такова южная граница.","20":"Западной границей будет Великое море, начиная с места, что лежит напротив Лево – Хамата. Такова западная граница.","21":"Эту землю вы разделите между собой – по племенам Израилевым.","22":"Вы должны раздать ее во владение себе и переселенцам, что поселились среди вас и родили детей. Эти люди должны быть для вас наравне с коренными израильтянами, вместе с вами они должны иметь свою долю среди племен Израилевых.","23":"Во владениях какого племени поселится переселенец – там и должны ему выделить его долю, – говорит Господь»."},"48":{"1":"Вот имена племен Израилевых. На самом севере, возле Хетлонской дороги, Лево – Хамата и Хацар – Энана, к северу от которого лежат владения Дамаска, близ от владений Хамата, простирается от восточных рубежей страны до западных земля Дана – это один надел.","2":"За владениями Дана простирается от восточных рубежей страны до западных земля Асира – это еще один надел.","3":"3а владениями Асира простирается от восточных рубежей страны до западных земля Неффалима – это еще один надел.","4":"За владениями Неффалима простирается от восточных рубежей страны до западных земля Манассии – это еще один надел.","5":"За владениями Манассии простирается от восточных рубежей страны до западных земля Ефрема – это еще один надел.","6":"За владениями Ефрема простирается от восточных рубежей страны до западных земля Рувима – это еще один надел.","7":"3а владениями Рувима простирается от восточных рубежей страны до западных земля Иуды – это еще один надел.","8":"За владениями Иуды простирается от восточных рубежей страны до западных обособленный участок земли. Ширина его двадцать пять тысяч локтей, длина – с востока на запад – такая же, как у наделов племен. На его территории будет находиться Святилище.","9":"Обособленный участок, который вы отделите для Господа, длиной будет двадцать пять тысяч локтей, а шириной – двадцать тысяч локтей.","10":"Священный надел, принадлежащий священникам, будет таким: северная его сторона – двадцать пять тысяч локтей; на западе ширина его десять тысяч локтей; на востоке ширина его десять тысяч локтей; южная его сторона – двадцать пять тысяч локтей. На его территории будет находиться Святилище Господа.","11":"Эта земля принадлежит священникам, которые соприкасаются со священным, – потомкам Цадока, несущим службу передо Мною. Они не отступились от Меня во время отступничества сынов Израилевых, как отступились левиты.","12":"Это будет их обособленный участок внутри обособленного участка страны, святыня святынь, возле надела левитов.","13":"Что же касается левитов, их надел лежит за наделом священников – двадцать пять тысяч локтей в длину и десять тысяч локтей в ширину. Общая длина этих земель – двадцать пять тысяч локтей, ширина – двадцать тысяч локтей.","14":"Нельзя эту землю ни продавать, ни обменивать, и она не должна переходить из рук в руки. Это особая земля, ибо она – святыня Господня.","15":"Оставшаяся полоса земли шириной пять тысяч локтей и длиной двадцать пять тысяч локтей не является священной, она предназначается Городу. Здесь будут жилища и пастбища, Город будет находиться посередине.","16":"Размеры Города таковы: северная сторона – четыре тысячи пятьсот локтей; южная сторона – четыре тысячи пятьсот локтей; на восточной стороне – четыре тысячи пятьсот локтей; западная сторона – четыре тысячи пятьсот.","17":"Город со всех сторон окружен пастбищами: с севера двести пятьдесят локтей, с юга двести пятьдесят локтей, с востока двести пятьдесят локтей и с запада – двести пятьдесят.","18":"Оставшаяся часть полосы, с юга примыкающей к обособленному священному участку, простирается к востоку от Города на десять тысяч локтей и к западу от Города – на десять тысяч локтей. Эти земли примыкают к границе священного участка; урожай с них должен идти на пропитание работающих в Городе.","19":"Работать в Городе будут люди из всех племен Израилевых; они и станут возделывать эту землю.","20":"Совокупный размер обособленного участка – двадцать пять тысяч локтей на двадцать пять тысяч локтей, он квадратный. Из него вы выделите священный участок, а также владения Города.","21":"Земли с той и другой стороны от священного участка и примыкающих к нему владений Города, принадлежат правителю. Полоса земли на восток, вплоть до восточных рубежей Земли Израилевой, шириной в двадцать пять тысяч локтей, и полоса земли на запад, вплоть до западных рубежей Земли Израилевой, шириной в двадцать пять тысяч локтей, принадлежат правителю. Их общая протяженность – такая же, как у наделов племен. Посреди владений правителя находится священный участок со Святилищем.","22":"И земли левитов, и земли Города лежат посредине владений правителя. Вся остальная полоса земли между владениями Иуды и владениями Вениамина будет принадлежать правителю.","23":"Что касается остальных племен. От восточных рубежей страны до западных простирается земля Вениамина – это еще один надел.","24":"За владениями Вениамина простирается от восточных рубежей страны до западных земля Симеона – это еще один надел.","25":"За владениями Симеона простирается от восточных рубежей страны до западных земля Иссахара – это еще один надел.","26":"За владениями Иссахара простирается от восточных рубежей страны до западных земля Завулона – это еще один надел.","27":"За владениями Завулона простирается от восточных рубежей страны до западных земля Гада – это еще один надел.","28":"Южная граница земель Гада идет от Тамара к водам Мериват – Кадеша, затем по ложбине к Великому морю.","29":"Вот земля, которую вы разделите по наделам среди племен Израилевых – и такими будут их владения, – говорит Господь Бог.","30":"О воротах в Городе, начиная с северной стороны (протяженность ее четыре тысячи пятьсот локтей).","31":"Ворота города названы по именам племен Израилевых. На северной стороне трое ворот: ворота Рувимовы, Иудины, Левиины.","32":"На восточной стороне (протяженность ее четыре тысячи пятьсот локтей) трое ворот: ворота Иосифовы, Вениаминовы, Дановы.","33":"На южной стороне (протяженность ее четыре тысячи пятьсот локтей) трое ворот: ворота Симеоновы, Иссахаровы, Завулоновы.","34":"На западной стороне (протяженностью четыре тысячи пятьсот локтей) тоже трое ворот: ворота Гадовы, Асировы, Неффалимовы.","35":"Общий периметр Города – восемнадцать тысяч локтей. И с того дня имя Городу будет «Господь там!»"}};
